-- Compare refresh part 3/5 — choose_a/b=text(json), faq=jsonb

-- hemingway-editor-vs-grammarly
UPDATE comparisons SET choose_a='["✅ You write content that needs to be clear, simple, and readable — blogs, emails, landing pages", "✅ You want to eliminate adverbs, passive voice, and complex sentences for stronger writing", "✅ You want a distraction-free editor focused purely on readability — no grammar nitpicking", "✅ You''re a writer who already knows grammar and needs structural feedback, not spell checking", "✅ You prefer a one-time-purchase desktop app (Hemingway Editor Classic) or a simple no-signup free online editor"]', choose_b='["✅ You want real-time grammar, spelling, and punctuation corrections as you type", "✅ You write in many places — the browser extension covers Gmail, Docs, Slack, and every text field", "✅ You want AI-powered tone detection, clarity suggestions, and full rewriting assistance", "✅ You want generative AI prompts to draft, reply, and rewrite — now part of the Superhuman suite", "✅ You need a free tier to start and a clear path to more AI usage as you scale"]', faq='[{"q": "What does Hemingway Editor do?", "a": "Hemingway Editor analyzes your writing for readability. It highlights hard-to-read and very-hard-to-read sentences, passive voice, complex phrases, and unnecessary adverbs — color-coded by severity — and assigns a grade-level readability score. The goal is writing that''s clear, direct, and easy to read."}, {"q": "Is Hemingway Editor free?", "a": "Yes, there''s a free online Hemingway Editor at hemingwayapp.com with readability highlighting and no signup required. For more, Hemingway Editor Plus is the paid, AI-powered web plan, and there''s also a one-time-purchase desktop app, Hemingway Editor Classic."}, {"q": "Is Grammarly better than Hemingway?", "a": "They do different things. Grammarly checks grammar, spelling, and style with real-time suggestions and AI writing, while Hemingway focuses on sentence structure and readability. Many writers use both: Grammarly for correctness, Hemingway for clarity. Grammarly is more comprehensive; Hemingway is more focused."}, {"q": "How much does Grammarly cost?", "a": "Grammarly has a Free plan at $0 with 100 AI prompts per month. Pro is about $12 per member/month billed annually (around $30/month monthly) with 2,000 AI prompts per month and a 7-day trial. Enterprise pricing is custom. Grammarly''s AI features are now part of the Superhuman suite."}]'::jsonb WHERE slug='hemingway-editor-vs-grammarly' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вы пишете тексты, которым нужна ясность, простота и читаемость — блоги, письма, лендинги", "✅ Вы хотите убрать наречия, пассивный залог и сложные предложения ради более сильного текста", "✅ Вам нужен редактор без отвлечений, сфокусированный именно на читаемости — без придирок к грамматике", "✅ Вы автор, который уже знает грамматику и нуждается в структурной обратной связи, а не в проверке орфографии", "✅ Вы предпочитаете десктопное приложение с разовой покупкой (Hemingway Editor Classic) или простой бесплатный онлайн-редактор без регистрации"]', choose_b='["✅ Вам нужны исправления грамматики, орфографии и пунктуации в реальном времени по мере набора", "✅ Вы пишете в разных местах — расширение для браузера работает в Gmail, Docs, Slack и любом текстовом поле", "✅ Вам нужны определение тона на базе ИИ, подсказки по ясности и полная помощь с переписыванием", "✅ Вам нужны генеративные ИИ-промпты для черновиков, ответов и переписывания — теперь в составе Superhuman suite", "✅ Вам нужен бесплатный тариф для старта и понятный путь к большему объёму ИИ по мере роста"]', faq='[{"q": "Что делает Hemingway Editor?", "a": "Hemingway Editor анализирует текст на читаемость. Он выделяет трудные и очень трудные для чтения предложения, пассивный залог, сложные фразы и лишние наречия — с цветовой маркировкой по степени — и присваивает оценку читаемости по уровню класса. Цель — ясный, прямой и лёгкий для чтения текст."}, {"q": "Hemingway Editor бесплатный?", "a": "Да, на hemingwayapp.com есть бесплатный онлайн-редактор Hemingway с подсветкой читаемости и без регистрации. Для большего есть Hemingway Editor Plus — платный веб-тариф с ИИ, а также десктопное приложение с разовой покупкой Hemingway Editor Classic."}, {"q": "Grammarly лучше, чем Hemingway?", "a": "Они решают разные задачи. Grammarly проверяет грамматику, орфографию и стиль с подсказками в реальном времени и ИИ-письмом, а Hemingway фокусируется на структуре предложений и читаемости. Многие авторы используют оба: Grammarly для корректности, Hemingway для ясности. Grammarly комплекснее, Hemingway сфокусированнее."}, {"q": "Сколько стоит Grammarly?", "a": "У Grammarly есть бесплатный тариф за $0 со 100 ИИ-промптами в месяц. Pro стоит около $12 за участника в месяц при годовой оплате (примерно $30/мес при помесячной) с 2000 ИИ-промптами в месяц и 7-дневным пробным периодом. Тариф Enterprise — по запросу. ИИ-функции Grammarly теперь входят в Superhuman suite."}]'::jsonb WHERE slug='hemingway-editor-vs-grammarly' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Escribes contenido que debe ser claro, simple y legible — blogs, correos, landing pages", "✅ Quieres eliminar adverbios, voz pasiva y frases complejas para una escritura más sólida", "✅ Quieres un editor sin distracciones centrado solo en la legibilidad — sin quisquillosidades gramaticales", "✅ Eres un escritor que ya domina la gramática y necesita retroalimentación estructural, no corrección ortográfica", "✅ Prefieres una app de escritorio de pago único (Hemingway Editor Classic) o un editor online gratuito y sin registro"]', choose_b='["✅ Quieres correcciones de gramática, ortografía y puntuación en tiempo real mientras escribes", "✅ Escribes en muchos lugares — la extensión del navegador cubre Gmail, Docs, Slack y cualquier campo de texto", "✅ Quieres detección de tono con IA, sugerencias de claridad y ayuda completa de reescritura", "✅ Quieres prompts de IA generativa para redactar, responder y reescribir — ahora parte de Superhuman suite", "✅ Necesitas un plan gratuito para empezar y una ruta clara a más uso de IA a medida que creces"]', faq='[{"q": "¿Qué hace Hemingway Editor?", "a": "Hemingway Editor analiza tu escritura en cuanto a legibilidad. Resalta las frases difíciles y muy difíciles de leer, la voz pasiva, las frases complejas y los adverbios innecesarios — con código de color por severidad — y asigna una puntuación de legibilidad por nivel escolar. El objetivo es una escritura clara, directa y fácil de leer."}, {"q": "¿Es gratis Hemingway Editor?", "a": "Sí, hay un editor online gratuito de Hemingway en hemingwayapp.com con resaltado de legibilidad y sin registro. Para más, Hemingway Editor Plus es el plan web de pago con IA, y también existe una app de escritorio de pago único, Hemingway Editor Classic."}, {"q": "¿Es Grammarly mejor que Hemingway?", "a": "Hacen cosas distintas. Grammarly revisa gramática, ortografía y estilo con sugerencias en tiempo real y escritura con IA, mientras que Hemingway se centra en la estructura de las frases y la legibilidad. Muchos escritores usan ambos: Grammarly para la corrección, Hemingway para la claridad. Grammarly es más completo; Hemingway, más enfocado."}, {"q": "¿Cuánto cuesta Grammarly?", "a": "Grammarly tiene un plan gratuito de $0 con 100 prompts de IA al mes. Pro cuesta unos $12 por miembro/mes con facturación anual (alrededor de $30/mes en pago mensual) con 2.000 prompts de IA al mes y prueba de 7 días. El plan Enterprise es a medida. Las funciones de IA de Grammarly ahora forman parte de Superhuman suite."}]'::jsonb WHERE slug='hemingway-editor-vs-grammarly' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du schreibst Inhalte, die klar, einfach und gut lesbar sein müssen — Blogs, E-Mails, Landingpages", "✅ Du willst Adverbien, Passiv und komplexe Sätze entfernen, um stärker zu schreiben", "✅ Du willst einen ablenkungsfreien Editor, der sich rein auf Lesbarkeit konzentriert — ohne Grammatik-Kleinkram", "✅ Du bist Autor, der Grammatik bereits beherrscht und strukturelles Feedback statt Rechtschreibprüfung braucht", "✅ Du bevorzugst eine Desktop-App mit Einmalkauf (Hemingway Editor Classic) oder einen einfachen kostenlosen Online-Editor ohne Anmeldung"]', choose_b='["✅ Du willst Grammatik-, Rechtschreib- und Zeichensetzungskorrekturen in Echtzeit beim Tippen", "✅ Du schreibst an vielen Stellen — die Browser-Erweiterung deckt Gmail, Docs, Slack und jedes Textfeld ab", "✅ Du willst KI-gestützte Tonerkennung, Klarheitsvorschläge und vollständige Umschreibhilfe", "✅ Du willst generative KI-Prompts zum Entwerfen, Antworten und Umschreiben — jetzt Teil der Superhuman-Suite", "✅ Du brauchst einen kostenlosen Tarif zum Start und einen klaren Weg zu mehr KI-Nutzung beim Wachsen"]', faq='[{"q": "Was macht Hemingway Editor?", "a": "Hemingway Editor analysiert deinen Text auf Lesbarkeit. Er hebt schwer und sehr schwer lesbare Sätze, Passiv, komplexe Formulierungen und überflüssige Adverbien hervor — farblich nach Schweregrad — und vergibt einen Lesbarkeitswert nach Klassenstufe. Das Ziel ist ein klarer, direkter und leicht lesbarer Text."}, {"q": "Ist Hemingway Editor kostenlos?", "a": "Ja, es gibt einen kostenlosen Online-Editor von Hemingway auf hemingwayapp.com mit Lesbarkeits-Hervorhebung und ohne Anmeldung. Für mehr ist Hemingway Editor Plus der kostenpflichtige, KI-gestützte Web-Tarif, und es gibt zudem eine Desktop-App mit Einmalkauf, Hemingway Editor Classic."}, {"q": "Ist Grammarly besser als Hemingway?", "a": "Sie tun Unterschiedliches. Grammarly prüft Grammatik, Rechtschreibung und Stil mit Echtzeitvorschlägen und KI-Schreiben, während sich Hemingway auf Satzstruktur und Lesbarkeit konzentriert. Viele Autoren nutzen beide: Grammarly für Korrektheit, Hemingway für Klarheit. Grammarly ist umfassender; Hemingway ist fokussierter."}, {"q": "Was kostet Grammarly?", "a": "Grammarly hat einen kostenlosen Tarif für $0 mit 100 KI-Prompts pro Monat. Pro kostet etwa $12 pro Mitglied/Monat bei jährlicher Abrechnung (rund $30/Monat bei monatlicher Zahlung) mit 2.000 KI-Prompts pro Monat und 7-tägiger Testphase. Enterprise-Preise sind individuell. Grammarlys KI-Funktionen sind nun Teil der Superhuman-Suite."}]'::jsonb WHERE slug='hemingway-editor-vs-grammarly' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Ви пишете контент, якому потрібна ясність, простота й читабельність — блоги, листи, лендинги", "✅ Ви хочете прибрати прислівники, пасивний стан і складні речення заради сильнішого тексту", "✅ Вам потрібен редактор без відволікань, зосереджений саме на читабельності — без прискіпувань до граматики", "✅ Ви автор, який уже знає граматику й потребує структурного зворотного зв''язку, а не перевірки орфографії", "✅ Ви віддаєте перевагу десктопному застосунку з разовою покупкою (Hemingway Editor Classic) або простому безкоштовному онлайн-редактору без реєстрації"]', choose_b='["✅ Вам потрібні виправлення граматики, орфографії та пунктуації в реальному часі під час набору", "✅ Ви пишете в багатьох місцях — розширення для браузера працює в Gmail, Docs, Slack і будь-якому текстовому полі", "✅ Вам потрібні визначення тону на основі ШІ, підказки щодо ясності та повна допомога з переписуванням", "✅ Вам потрібні генеративні ШІ-промпти для чернеток, відповідей і переписування — тепер у складі Superhuman suite", "✅ Вам потрібен безкоштовний тариф для старту та зрозумілий шлях до більшого обсягу ШІ в міру зростання"]', faq='[{"q": "Що робить Hemingway Editor?", "a": "Hemingway Editor аналізує ваш текст на читабельність. Він підсвічує важкі та дуже важкі для читання речення, пасивний стан, складні фрази й зайві прислівники — з кольоровим маркуванням за ступенем — і присвоює оцінку читабельності за рівнем класу. Мета — ясний, прямий і легкий для читання текст."}, {"q": "Чи безкоштовний Hemingway Editor?", "a": "Так, на hemingwayapp.com є безкоштовний онлайн-редактор Hemingway з підсвічуванням читабельності й без реєстрації. Для більшого є Hemingway Editor Plus — платний веб-тариф зі ШІ, а також десктопний застосунок з разовою покупкою Hemingway Editor Classic."}, {"q": "Grammarly кращий за Hemingway?", "a": "Вони роблять різні речі. Grammarly перевіряє граматику, орфографію та стиль із підказками в реальному часі й письмом на основі ШІ, а Hemingway зосереджується на структурі речень і читабельності. Багато авторів використовують обидва: Grammarly для коректності, Hemingway для ясності. Grammarly комплексніший, Hemingway сфокусованіший."}, {"q": "Скільки коштує Grammarly?", "a": "У Grammarly є безкоштовний тариф за $0 зі 100 ШІ-промптами на місяць. Pro коштує близько $12 за учасника на місяць при річній оплаті (приблизно $30/міс при щомісячній) з 2000 ШІ-промптами на місяць і 7-денним пробним періодом. Тариф Enterprise — за запитом. ШІ-функції Grammarly тепер входять до Superhuman suite."}]'::jsonb WHERE slug='hemingway-editor-vs-grammarly' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם כותבים תוכן שצריך להיות ברור, פשוט וקריא — בלוגים, אימיילים, דפי נחיתה", "✅ אתם רוצים לחסל תוארי פועל, סביל ומשפטים מורכבים לכתיבה חזקה יותר", "✅ אתם רוצים עורך נטול הסחות דעת שממוקד אך ורק בקריאוּת — בלי קטנוניות דקדוקית", "✅ אתם כותבים שכבר שולטים בדקדוק וזקוקים למשוב מבני, לא לבדיקת איות", "✅ אתם מעדיפים אפליקציית דסקטופ ברכישה חד-פעמית (Hemingway Editor Classic) או עורך אונליין חינמי ופשוט ללא הרשמה"]', choose_b='["✅ אתם רוצים תיקוני דקדוק, איות ופיסוק בזמן אמת תוך כדי הקלדה", "✅ אתם כותבים בהרבה מקומות — תוסף הדפדפן מכסה את Gmail, Docs, Slack וכל שדה טקסט", "✅ אתם רוצים זיהוי טון מבוסס בינה מלאכותית, הצעות לבהירות ועזרה מלאה בשכתוב", "✅ אתם רוצים פרומפטים של בינה מלאכותית יוצרת לניסוח, מענה ושכתוב — כעת חלק מ-Superhuman suite", "✅ אתם צריכים תוכנית חינמית להתחלה ומסלול ברור ליותר שימוש בבינה מלאכותית ככל שתגדלו"]', faq='[{"q": "מה עושה Hemingway Editor?", "a": "Hemingway Editor מנתח את הכתיבה שלכם מבחינת קריאוּת. הוא מדגיש משפטים קשים וקשים מאוד לקריאה, סביל, ביטויים מורכבים ותוארי פועל מיותרים — בקוד צבעים לפי חומרה — ומעניק ציון קריאוּת לפי רמת כיתה. המטרה היא כתיבה ברורה, ישירה וקלה לקריאה."}, {"q": "האם Hemingway Editor חינמי?", "a": "כן, יש עורך אונליין חינמי של Hemingway בכתובת hemingwayapp.com עם הדגשת קריאוּת וללא הרשמה. למעבר מעבר לכך, Hemingway Editor Plus היא תוכנית ווב בתשלום מבוססת בינה מלאכותית, ויש גם אפליקציית דסקטופ ברכישה חד-פעמית, Hemingway Editor Classic."}, {"q": "האם Grammarly טוב יותר מ-Hemingway?", "a": "הם עושים דברים שונים. Grammarly בודק דקדוק, איות וסגנון עם הצעות בזמן אמת וכתיבה בבינה מלאכותית, בעוד Hemingway מתמקד במבנה המשפט ובקריאוּת. כותבים רבים משתמשים בשניהם: Grammarly לתקינות, Hemingway לבהירות. Grammarly מקיף יותר; Hemingway ממוקד יותר."}, {"q": "כמה עולה Grammarly?", "a": "ל-Grammarly יש תוכנית חינמית ב-$0 עם 100 פרומפטים של בינה מלאכותית בחודש. Pro עולה כ-$12 לחבר לחודש בחיוב שנתי (כ-$30 לחודש בתשלום חודשי) עם 2,000 פרומפטים בחודש ותקופת ניסיון של 7 ימים. תמחור Enterprise מותאם אישית. יכולות הבינה המלאכותית של Grammarly הן כעת חלק מ-Superhuman suite."}]'::jsonb WHERE slug='hemingway-editor-vs-grammarly' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous écrivez du contenu qui doit être clair, simple et lisible — blogs, e-mails, landing pages", "✅ Vous voulez éliminer les adverbes, la voix passive et les phrases complexes pour une écriture plus percutante", "✅ Vous voulez un éditeur sans distraction centré uniquement sur la lisibilité — sans chipotage grammatical", "✅ Vous êtes un rédacteur qui maîtrise déjà la grammaire et a besoin de retours structurels, pas d''un correcteur orthographique", "✅ Vous préférez une application de bureau en achat unique (Hemingway Editor Classic) ou un éditeur en ligne gratuit et sans inscription"]', choose_b='["✅ Vous voulez des corrections de grammaire, d''orthographe et de ponctuation en temps réel pendant la frappe", "✅ Vous écrivez à de nombreux endroits — l''extension de navigateur couvre Gmail, Docs, Slack et tous les champs de texte", "✅ Vous voulez une détection du ton par IA, des suggestions de clarté et une aide complète à la réécriture", "✅ Vous voulez des prompts d''IA générative pour rédiger, répondre et réécrire — désormais intégrés à la suite Superhuman", "✅ Vous avez besoin d''un forfait gratuit pour démarrer et d''une voie claire vers plus d''usage de l''IA à mesure que vous grandissez"]', faq='[{"q": "Que fait Hemingway Editor ?", "a": "Hemingway Editor analyse la lisibilité de votre texte. Il met en évidence les phrases difficiles et très difficiles à lire, la voix passive, les formulations complexes et les adverbes superflus — avec un code couleur selon la gravité — et attribue un score de lisibilité par niveau scolaire. L''objectif est une écriture claire, directe et facile à lire."}, {"q": "Hemingway Editor est-il gratuit ?", "a": "Oui, il existe un éditeur Hemingway en ligne gratuit sur hemingwayapp.com avec surlignage de lisibilité et sans inscription. Pour aller plus loin, Hemingway Editor Plus est l''offre web payante dotée d''IA, et il existe aussi une application de bureau en achat unique, Hemingway Editor Classic."}, {"q": "Grammarly est-il meilleur que Hemingway ?", "a": "Ils font des choses différentes. Grammarly vérifie la grammaire, l''orthographe et le style avec des suggestions en temps réel et une écriture par IA, tandis que Hemingway se concentre sur la structure des phrases et la lisibilité. De nombreux rédacteurs utilisent les deux : Grammarly pour la correction, Hemingway pour la clarté. Grammarly est plus complet ; Hemingway est plus ciblé."}, {"q": "Combien coûte Grammarly ?", "a": "Grammarly propose un forfait gratuit à 0 $ avec 100 prompts d''IA par mois. Pro coûte environ 12 $ par membre/mois en facturation annuelle (environ 30 $/mois en mensuel) avec 2 000 prompts d''IA par mois et un essai de 7 jours. Le tarif Enterprise est sur devis. Les fonctions d''IA de Grammarly font désormais partie de la suite Superhuman."}]'::jsonb WHERE slug='hemingway-editor-vs-grammarly' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você escreve conteúdo que precisa ser claro, simples e legível — blogs, e-mails, landing pages", "✅ Você quer eliminar advérbios, voz passiva e frases complexas para uma escrita mais forte", "✅ Você quer um editor sem distrações focado apenas na legibilidade — sem implicância gramatical", "✅ Você é um escritor que já domina a gramática e precisa de feedback estrutural, não de correção ortográfica", "✅ Você prefere um app de desktop de compra única (Hemingway Editor Classic) ou um editor online gratuito e sem cadastro"]', choose_b='["✅ Você quer correções de gramática, ortografia e pontuação em tempo real enquanto digita", "✅ Você escreve em muitos lugares — a extensão de navegador cobre Gmail, Docs, Slack e qualquer campo de texto", "✅ Você quer detecção de tom com IA, sugestões de clareza e ajuda completa de reescrita", "✅ Você quer prompts de IA generativa para rascunhar, responder e reescrever — agora parte da suíte Superhuman", "✅ Você precisa de um plano gratuito para começar e um caminho claro para mais uso de IA conforme cresce"]', faq='[{"q": "O que o Hemingway Editor faz?", "a": "O Hemingway Editor analisa a legibilidade do seu texto. Ele destaca frases difíceis e muito difíceis de ler, voz passiva, expressões complexas e advérbios desnecessários — com código de cores por gravidade — e atribui uma pontuação de legibilidade por nível escolar. O objetivo é uma escrita clara, direta e fácil de ler."}, {"q": "O Hemingway Editor é gratuito?", "a": "Sim, há um editor online gratuito do Hemingway em hemingwayapp.com com destaque de legibilidade e sem cadastro. Para mais, o Hemingway Editor Plus é o plano web pago com IA, e também existe um app de desktop de compra única, o Hemingway Editor Classic."}, {"q": "O Grammarly é melhor que o Hemingway?", "a": "Eles fazem coisas diferentes. O Grammarly verifica gramática, ortografia e estilo com sugestões em tempo real e escrita com IA, enquanto o Hemingway foca na estrutura das frases e na legibilidade. Muitos escritores usam os dois: Grammarly para correção, Hemingway para clareza. O Grammarly é mais abrangente; o Hemingway é mais focado."}, {"q": "Quanto custa o Grammarly?", "a": "O Grammarly tem um plano gratuito de US$ 0 com 100 prompts de IA por mês. O Pro custa cerca de US$ 12 por membro/mês na cobrança anual (cerca de US$ 30/mês no mensal) com 2.000 prompts de IA por mês e teste de 7 dias. O preço Enterprise é personalizado. Os recursos de IA do Grammarly agora fazem parte da suíte Superhuman."}]'::jsonb WHERE slug='hemingway-editor-vs-grammarly' AND lang='pt';

-- ideogram-vs-midjourney
UPDATE comparisons SET choose_a='["✅ You need text rendered accurately inside images — logos, posters, t-shirt designs, typography", "✅ You create graphic design assets where legible text within the image is essential", "✅ You want a free tier to start — Ideogram''s free plan offers weekly generations at no cost", "✅ You need strong prompt adherence that reliably produces what you describe, not loose artistic interpretation"]', choose_b='["✅ You prioritize raw visual quality and aesthetic beauty — Midjourney leads on artistic output", "✅ You create photography-style images, concept art, or illustrations where style matters most", "✅ You want the largest AI art community for prompt inspiration and sharing", "✅ You work in creative fields where visual excellence beats text accuracy"]', faq='[{"q": "What is Ideogram AI?", "a": "Ideogram is an AI image generator specifically optimized for rendering text within images. It excels at creating posters, logos, t-shirt designs, and any image where readable text is part of the visual. The current Ideogram 4.0 (released June 2026) also delivers strong photorealism and design capabilities."}, {"q": "Can Midjourney generate text in images?", "a": "Midjourney V7 improved text rendering, but it still struggles with accurate, legible text compared to Ideogram. For images where text accuracy is critical — signs, logos, product labels — Ideogram remains the better choice."}, {"q": "Is Ideogram free?", "a": "Ideogram has a free plan ($0) with roughly 10 slow credits per week and public generations. Paid tiers start with Basic at about $8/month (around $7/month billed annually) for priority credits, and Plus at about $20/month (around $15-16/month billed annually)."}, {"q": "How much does Midjourney cost?", "a": "Midjourney has no free tier. Plans are Basic $10/month, Standard $30/month, Pro $60/month, and Mega $120/month, with higher tiers adding more fast GPU time and concurrency."}]'::jsonb WHERE slug='ideogram-vs-midjourney' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вам нужен точный текст внутри изображений — логотипы, постеры, дизайны для футболок, типографика", "✅ Вы создаёте графические ассеты, где читаемый текст на изображении критически важен", "✅ Вам нужен бесплатный старт — у Ideogram есть бесплатный план с еженедельными генерациями", "✅ Вам важно точное следование промпту, которое надёжно выдаёт описанное, а не вольную художественную интерпретацию"]', choose_b='["✅ Для вас в приоритете визуальное качество и эстетика — Midjourney лидирует по художественному результату", "✅ Вы создаёте фотореалистичные изображения, концепт-арт или иллюстрации, где важнее всего стиль", "✅ Вам нужно крупнейшее сообщество AI-арта для вдохновения и обмена промптами", "✅ Вы работаете в креативных сферах, где визуальное совершенство важнее точности текста"]', faq='[{"q": "Что такое Ideogram AI?", "a": "Ideogram — это генератор изображений на базе ИИ, специально оптимизированный для отрисовки текста внутри изображений. Он отлично справляется с постерами, логотипами, дизайнами для футболок и любыми изображениями, где читаемый текст является частью визуала. Актуальная версия Ideogram 4.0 (выпущена в июне 2026) также обеспечивает сильный фотореализм и дизайнерские возможности."}, {"q": "Может ли Midjourney генерировать текст на изображениях?", "a": "Midjourney V7 улучшил отрисовку текста, но по-прежнему уступает Ideogram в точности и читаемости. Для изображений, где важна точность текста — вывески, логотипы, этикетки товаров — Ideogram остаётся лучшим выбором."}, {"q": "Ideogram бесплатный?", "a": "У Ideogram есть бесплатный план ($0) примерно с 10 медленными кредитами в неделю и публичными генерациями. Платные тарифы начинаются с Basic — около $8/мес (примерно $7/мес при годовой оплате) с приоритетными кредитами, и Plus — около $20/мес (примерно $15-16/мес при годовой оплате)."}, {"q": "Сколько стоит Midjourney?", "a": "У Midjourney нет бесплатного тарифа. Планы: Basic $10/мес, Standard $30/мес, Pro $60/мес и Mega $120/мес; старшие тарифы дают больше быстрого GPU-времени и параллельных генераций."}]'::jsonb WHERE slug='ideogram-vs-midjourney' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Necesitas texto renderizado con precisión dentro de las imágenes — logos, pósters, diseños de camisetas, tipografía", "✅ Creas recursos de diseño gráfico donde el texto legible dentro de la imagen es esencial", "✅ Quieres empezar gratis — el plan gratuito de Ideogram ofrece generaciones semanales sin coste", "✅ Necesitas una fiel adherencia al prompt que produzca lo que describes, no una interpretación artística libre"]', choose_b='["✅ Priorizas la calidad visual pura y la belleza estética — Midjourney lidera en resultado artístico", "✅ Creas imágenes estilo fotografía, arte conceptual o ilustraciones donde el estilo importa más", "✅ Quieres la mayor comunidad de arte con IA para inspiración de prompts y compartir", "✅ Trabajas en campos creativos donde la excelencia visual supera a la precisión del texto"]', faq='[{"q": "¿Qué es Ideogram AI?", "a": "Ideogram es un generador de imágenes con IA optimizado específicamente para renderizar texto dentro de las imágenes. Destaca creando pósters, logos, diseños de camisetas y cualquier imagen donde el texto legible forma parte del visual. La versión actual, Ideogram 4.0 (lanzada en junio de 2026), también ofrece un fuerte fotorrealismo y capacidades de diseño."}, {"q": "¿Puede Midjourney generar texto en imágenes?", "a": "Midjourney V7 mejoró el renderizado de texto, pero sigue teniendo dificultades para lograr texto preciso y legible frente a Ideogram. Para imágenes donde la precisión del texto es crítica — carteles, logos, etiquetas de producto — Ideogram sigue siendo la mejor opción."}, {"q": "¿Ideogram es gratis?", "a": "Ideogram tiene un plan gratuito ($0) con unos 10 créditos lentos por semana y generaciones públicas. Los planes de pago comienzan con Basic por unos $8/mes (alrededor de $7/mes con facturación anual) con créditos prioritarios, y Plus por unos $20/mes (alrededor de $15-16/mes con facturación anual)."}, {"q": "¿Cuánto cuesta Midjourney?", "a": "Midjourney no tiene plan gratuito. Los planes son Basic $10/mes, Standard $30/mes, Pro $60/mes y Mega $120/mes; los niveles superiores añaden más tiempo de GPU rápido y concurrencia."}]'::jsonb WHERE slug='ideogram-vs-midjourney' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du brauchst präzise gerenderten Text in Bildern — Logos, Poster, T-Shirt-Designs, Typografie", "✅ Du erstellst Grafikdesign-Assets, bei denen lesbarer Text im Bild entscheidend ist", "✅ Du willst kostenlos starten — der Gratis-Plan von Ideogram bietet wöchentliche Generierungen ohne Kosten", "✅ Du brauchst eine zuverlässige Prompt-Treue, die genau das liefert, was du beschreibst, statt freier künstlerischer Interpretation"]', choose_b='["✅ Dir sind reine Bildqualität und ästhetische Schönheit am wichtigsten — Midjourney führt beim künstlerischen Ergebnis", "✅ Du erstellst fotorealistische Bilder, Concept Art oder Illustrationen, bei denen der Stil am meisten zählt", "✅ Du willst die größte KI-Kunst-Community für Prompt-Inspiration und Austausch", "✅ Du arbeitest in kreativen Bereichen, in denen visuelle Exzellenz wichtiger ist als Textgenauigkeit"]', faq='[{"q": "Was ist Ideogram AI?", "a": "Ideogram ist ein KI-Bildgenerator, der speziell auf das Rendern von Text in Bildern optimiert ist. Er glänzt bei Postern, Logos, T-Shirt-Designs und allen Bildern, bei denen lesbarer Text Teil des Motivs ist. Die aktuelle Version Ideogram 4.0 (veröffentlicht im Juni 2026) bietet zudem starken Fotorealismus und Design-Fähigkeiten."}, {"q": "Kann Midjourney Text in Bildern erzeugen?", "a": "Midjourney V7 hat das Text-Rendering verbessert, hat aber im Vergleich zu Ideogram weiterhin Probleme mit präzisem, lesbarem Text. Für Bilder, bei denen Textgenauigkeit entscheidend ist — Schilder, Logos, Produktetiketten — bleibt Ideogram die bessere Wahl."}, {"q": "Ist Ideogram kostenlos?", "a": "Ideogram hat einen kostenlosen Plan ($0) mit etwa 10 langsamen Credits pro Woche und öffentlichen Generierungen. Die kostenpflichtigen Stufen beginnen mit Basic für etwa 8 $/Monat (rund 7 $/Monat bei jährlicher Abrechnung) mit priorisierten Credits und Plus für etwa 20 $/Monat (rund 15-16 $/Monat bei jährlicher Abrechnung)."}, {"q": "Was kostet Midjourney?", "a": "Midjourney hat keine kostenlose Stufe. Die Pläne sind Basic 10 $/Monat, Standard 30 $/Monat, Pro 60 $/Monat und Mega 120 $/Monat; höhere Stufen bieten mehr schnelle GPU-Zeit und Parallelität."}]'::jsonb WHERE slug='ideogram-vs-midjourney' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Вам потрібен точний текст усередині зображень — логотипи, постери, дизайни для футболок, типографіка", "✅ Ви створюєте графічні ассети, де читабельний текст на зображенні критично важливий", "✅ Ви хочете безкоштовний старт — у Ideogram є безкоштовний план із щотижневими генераціями", "✅ Вам потрібне точне дотримання промпту, що надійно видає описане, а не вільну художню інтерпретацію"]', choose_b='["✅ Для вас у пріоритеті візуальна якість та естетика — Midjourney лідирує за художнім результатом", "✅ Ви створюєте фотореалістичні зображення, концепт-арт чи ілюстрації, де найважливіший стиль", "✅ Вам потрібна найбільша спільнота AI-арту для натхнення та обміну промптами", "✅ Ви працюєте у креативних сферах, де візуальна досконалість важливіша за точність тексту"]', faq='[{"q": "Що таке Ideogram AI?", "a": "Ideogram — це генератор зображень на основі ШІ, спеціально оптимізований для відтворення тексту всередині зображень. Він чудово впорається з постерами, логотипами, дизайнами для футболок і будь-якими зображеннями, де читабельний текст є частиною візуалу. Актуальна версія Ideogram 4.0 (випущена в червні 2026) також забезпечує сильний фотореалізм і дизайнерські можливості."}, {"q": "Чи може Midjourney генерувати текст на зображеннях?", "a": "Midjourney V7 покращив відтворення тексту, але все ще поступається Ideogram у точності та читабельності. Для зображень, де важлива точність тексту — вивіски, логотипи, етикетки товарів — Ideogram залишається кращим вибором."}, {"q": "Ideogram безкоштовний?", "a": "У Ideogram є безкоштовний план ($0) приблизно з 10 повільними кредитами на тиждень та публічними генераціями. Платні тарифи починаються з Basic — близько $8/міс (приблизно $7/міс за річної оплати) з пріоритетними кредитами, і Plus — близько $20/міс (приблизно $15-16/міс за річної оплати)."}, {"q": "Скільки коштує Midjourney?", "a": "У Midjourney немає безкоштовного тарифу. Плани: Basic $10/міс, Standard $30/міс, Pro $60/міс та Mega $120/міс; старші тарифи дають більше швидкого GPU-часу та паралельних генерацій."}]'::jsonb WHERE slug='ideogram-vs-midjourney' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם צריכים טקסט מדויק בתוך התמונות — לוגואים, פוסטרים, עיצובי חולצות, טיפוגרפיה", "✅ אתם יוצרים נכסי עיצוב גרפי שבהם טקסט קריא בתוך התמונה הוא חיוני", "✅ אתם רוצים להתחיל בחינם — התוכנית החינמית של Ideogram מציעה יצירות שבועיות ללא עלות", "✅ אתם צריכים היצמדות אמינה לפרומפט שמפיקה בדיוק את מה שתיארתם, ולא פרשנות אמנותית חופשית"]', choose_b='["✅ אתם מעדיפים איכות חזותית גולמית ויופי אסתטי — Midjourney מובילה בתוצאה האמנותית", "✅ אתם יוצרים תמונות בסגנון צילום, קונספט ארט או איורים שבהם הסגנון הכי חשוב", "✅ אתם רוצים את קהילת אמנות ה-AI הגדולה ביותר להשראה ולשיתוף פרומפטים", "✅ אתם עובדים בתחומים יצירתיים שבהם מצוינות חזותית גוברת על דיוק הטקסט"]', faq='[{"q": "מה זה Ideogram AI?", "a": "Ideogram הוא מחולל תמונות מבוסס AI שמותאם במיוחד ליצירת טקסט בתוך תמונות. הוא מצטיין ביצירת פוסטרים, לוגואים, עיצובי חולצות וכל תמונה שבה טקסט קריא הוא חלק מהוויזואל. הגרסה הנוכחית Ideogram 4.0 (שוחררה ביוני 2026) מספקת גם פוטוריאליזם חזק ויכולות עיצוב."}, {"q": "האם Midjourney יכולה ליצור טקסט בתמונות?", "a": "Midjourney V7 שיפרה את יצירת הטקסט, אך היא עדיין מתקשה בטקסט מדויק וקריא בהשוואה ל-Ideogram. לתמונות שבהן דיוק הטקסט קריטי — שלטים, לוגואים, תוויות מוצר — Ideogram נשארת הבחירה הטובה יותר."}, {"q": "האם Ideogram חינמי?", "a": "ל-Ideogram יש תוכנית חינמית ($0) עם כ-10 קרדיטים איטיים בשבוע ויצירות פומביות. התוכניות בתשלום מתחילות ב-Basic בכ-8$ לחודש (כ-7$ לחודש בחיוב שנתי) עם קרדיטים מועדפים, ו-Plus בכ-20$ לחודש (כ-15-16$ לחודש בחיוב שנתי)."}, {"q": "כמה עולה Midjourney?", "a": "ל-Midjourney אין תוכנית חינמית. התוכניות הן Basic ב-10$ לחודש, Standard ב-30$ לחודש, Pro ב-60$ לחודש ו-Mega ב-120$ לחודש; הרמות הגבוהות מוסיפות יותר זמן GPU מהיר ומקביליות."}]'::jsonb WHERE slug='ideogram-vs-midjourney' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous avez besoin d''un texte rendu avec précision dans les images — logos, affiches, designs de t-shirts, typographie", "✅ Vous créez des ressources de design graphique où un texte lisible dans l''image est essentiel", "✅ Vous voulez démarrer gratuitement — le plan gratuit d''Ideogram offre des générations hebdomadaires sans frais", "✅ Vous avez besoin d''une fidélité au prompt qui produit exactement ce que vous décrivez, plutôt qu''une interprétation artistique libre"]', choose_b='["✅ Vous privilégiez la qualité visuelle brute et la beauté esthétique — Midjourney domine sur le rendu artistique", "✅ Vous créez des images de style photographique, du concept art ou des illustrations où le style prime", "✅ Vous voulez la plus grande communauté d''art IA pour l''inspiration et le partage de prompts", "✅ Vous travaillez dans des domaines créatifs où l''excellence visuelle prime sur la précision du texte"]', faq='[{"q": "Qu''est-ce qu''Ideogram AI ?", "a": "Ideogram est un générateur d''images par IA spécialement optimisé pour le rendu de texte dans les images. Il excelle dans la création d''affiches, de logos, de designs de t-shirts et de toute image où un texte lisible fait partie du visuel. La version actuelle, Ideogram 4.0 (sortie en juin 2026), offre également un fort photoréalisme et des capacités de design."}, {"q": "Midjourney peut-il générer du texte dans les images ?", "a": "Midjourney V7 a amélioré le rendu du texte, mais il peine encore à produire un texte précis et lisible comparé à Ideogram. Pour les images où la précision du texte est cruciale — panneaux, logos, étiquettes de produits — Ideogram reste le meilleur choix."}, {"q": "Ideogram est-il gratuit ?", "a": "Ideogram propose un plan gratuit (0 $) avec environ 10 crédits lents par semaine et des générations publiques. Les offres payantes débutent avec Basic à environ 8 $/mois (environ 7 $/mois en facturation annuelle) avec des crédits prioritaires, et Plus à environ 20 $/mois (environ 15-16 $/mois en facturation annuelle)."}, {"q": "Combien coûte Midjourney ?", "a": "Midjourney n''a pas d''offre gratuite. Les plans sont Basic à 10 $/mois, Standard à 30 $/mois, Pro à 60 $/mois et Mega à 120 $/mois ; les niveaux supérieurs ajoutent plus de temps GPU rapide et de concurrence."}]'::jsonb WHERE slug='ideogram-vs-midjourney' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você precisa de texto renderizado com precisão dentro das imagens — logos, pôsteres, designs de camisetas, tipografia", "✅ Você cria recursos de design gráfico onde o texto legível dentro da imagem é essencial", "✅ Você quer começar de graça — o plano gratuito do Ideogram oferece gerações semanais sem custo", "✅ Você precisa de fidelidade ao prompt que produza de forma confiável o que você descreve, e não uma interpretação artística livre"]', choose_b='["✅ Você prioriza a qualidade visual pura e a beleza estética — o Midjourney lidera no resultado artístico", "✅ Você cria imagens em estilo fotográfico, concept art ou ilustrações onde o estilo importa mais", "✅ Você quer a maior comunidade de arte com IA para inspiração e compartilhamento de prompts", "✅ Você trabalha em áreas criativas onde a excelência visual supera a precisão do texto"]', faq='[{"q": "O que é o Ideogram AI?", "a": "O Ideogram é um gerador de imagens com IA otimizado especificamente para renderizar texto dentro das imagens. Ele se destaca na criação de pôsteres, logos, designs de camisetas e qualquer imagem em que o texto legível faça parte do visual. A versão atual, Ideogram 4.0 (lançada em junho de 2026), também oferece forte fotorrealismo e recursos de design."}, {"q": "O Midjourney consegue gerar texto em imagens?", "a": "O Midjourney V7 melhorou a renderização de texto, mas ainda tem dificuldade em produzir texto preciso e legível em comparação com o Ideogram. Para imagens em que a precisão do texto é crítica — placas, logos, rótulos de produtos — o Ideogram continua sendo a melhor escolha."}, {"q": "O Ideogram é gratuito?", "a": "O Ideogram tem um plano gratuito ($0) com cerca de 10 créditos lentos por semana e gerações públicas. Os planos pagos começam com o Basic por cerca de $8/mês (cerca de $7/mês na cobrança anual) com créditos prioritários, e o Plus por cerca de $20/mês (cerca de $15-16/mês na cobrança anual)."}, {"q": "Quanto custa o Midjourney?", "a": "O Midjourney não tem plano gratuito. Os planos são Basic $10/mês, Standard $30/mês, Pro $60/mês e Mega $120/mês; os níveis superiores adicionam mais tempo de GPU rápido e concorrência."}]'::jsonb WHERE slug='ideogram-vs-midjourney' AND lang='pt';

-- khanmigo-vs-photomath
UPDATE comparisons SET choose_a='["✅ You need help across multiple academic subjects — not just math, but science, history, and writing", "✅ You want a Socratic tutor that guides you to the answer with questions rather than just solving it", "✅ You''re a teacher who wants free AI tools for lesson planning, student feedback, and class prep", "✅ You use Khan Academy''s curriculum and want AI integrated directly into those lessons"]', choose_b='["✅ You need quick, step-by-step solutions to math problems from a photo on your phone", "✅ You want immediate worked answers rather than Socratic guidance", "✅ You''re a student who needs math homework help fast, from arithmetic to calculus", "✅ You want a genuinely free core app with unlimited step-by-step solutions and no ads"]', faq='[{"q": "What is Khanmigo?", "a": "Khanmigo is Khan Academy''s GPT-4-powered AI tutor. It uses the Socratic method — asking guiding questions rather than handing over answers — to help students understand concepts across math, science, history, and the humanities. Khan Academy is rolling out GPT-4o multimodal integration and piloting a summer 2026 redesign."}, {"q": "Is Photomath free?", "a": "Yes. Photomath''s core app is completely free with unlimited step-by-step solutions, camera scan, a calculator, no ads, and no time limit. Photomath Plus ($9.99/month or $69.99/year, about $5.83/month) adds animated explanations and multiple solution methods."}, {"q": "Is Khanmigo free?", "a": "For teachers, yes — Khanmigo is free in 44+ countries, supported by Microsoft. Learners and parents/families pay $4/month or $44/year (the annual plan saves roughly two months), and a parent account can add up to 10 children."}, {"q": "Can Photomath solve word problems?", "a": "Yes. You can type or photograph text-based math problems, not just equations, and Photomath handles algebra word problems. Complex multi-step reasoning problems may still be better suited to a broader tutor like Khanmigo."}]'::jsonb WHERE slug='khanmigo-vs-photomath' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вам нужна помощь по нескольким школьным предметам — не только по математике, но и по естественным наукам, истории и письму", "✅ Вы хотите сократического наставника, который наводящими вопросами ведёт вас к ответу, а не просто решает задачу", "✅ Вы преподаватель и хотите бесплатные ИИ-инструменты для планирования уроков, обратной связи ученикам и подготовки к занятиям", "✅ Вы учитесь по программе Khan Academy и хотите, чтобы ИИ был встроен прямо в эти уроки"]', choose_b='["✅ Вам нужны быстрые пошаговые решения задач по математике прямо с фотографии на телефоне", "✅ Вам нужны готовые решения сразу, а не сократические подсказки", "✅ Вы студент и вам срочно нужна помощь с домашкой по математике — от арифметики до матанализа", "✅ Вам нужно по-настоящему бесплатное приложение с безлимитными пошаговыми решениями и без рекламы"]', faq='[{"q": "Что такое Khanmigo?", "a": "Khanmigo — это ИИ-репетитор Khan Academy на базе GPT-4. Он использует сократический метод — задаёт наводящие вопросы вместо готовых ответов — и помогает разобраться в темах по математике, естественным наукам, истории и гуманитарным дисциплинам. Khan Academy внедряет мультимодальную интеграцию GPT-4o и тестирует обновлённый дизайн летом 2026 года."}, {"q": "Photomath бесплатный?", "a": "Да. Основное приложение Photomath полностью бесплатно: безлимитные пошаговые решения, сканирование камерой, калькулятор, без рекламы и без ограничений по времени. Photomath Plus ($9,99/месяц или $69,99/год, около $5,83/месяц) добавляет анимированные объяснения и несколько способов решения."}, {"q": "Khanmigo бесплатный?", "a": "Для преподавателей — да: Khanmigo бесплатен в 44+ странах при поддержке Microsoft. Ученики и родители/семьи платят $4/месяц или $44/год (годовой план экономит около двух месяцев), а к родительскому аккаунту можно добавить до 10 детей."}, {"q": "Может ли Photomath решать текстовые задачи?", "a": "Да. Можно ввести текст или сфотографировать текстовую задачу, а не только уравнение, и Photomath справится с алгебраическими текстовыми задачами. Для сложных задач с многошаговыми рассуждениями лучше подойдёт более широкий наставник вроде Khanmigo."}]'::jsonb WHERE slug='khanmigo-vs-photomath' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Necesitas ayuda en varias materias académicas — no solo matemáticas, sino también ciencias, historia y escritura", "✅ Quieres un tutor socrático que te guíe hacia la respuesta con preguntas en lugar de resolverla directamente", "✅ Eres docente y buscas herramientas de IA gratuitas para planificar clases, dar retroalimentación y preparar tus lecciones", "✅ Usas el plan de estudios de Khan Academy y quieres la IA integrada directamente en esas lecciones"]', choose_b='["✅ Necesitas soluciones rápidas y paso a paso de problemas de matemáticas a partir de una foto en tu teléfono", "✅ Quieres respuestas resueltas de inmediato en lugar de una guía socrática", "✅ Eres estudiante y necesitas ayuda rápida con la tarea de matemáticas, desde aritmética hasta cálculo", "✅ Quieres una app con núcleo realmente gratuito, con soluciones paso a paso ilimitadas y sin anuncios"]', faq='[{"q": "¿Qué es Khanmigo?", "a": "Khanmigo es el tutor de IA de Khan Academy impulsado por GPT-4. Utiliza el método socrático —hace preguntas orientadoras en lugar de dar la respuesta— para ayudar a los estudiantes a comprender conceptos de matemáticas, ciencias, historia y humanidades. Khan Academy está implementando la integración multimodal de GPT-4o y probando un rediseño en el verano de 2026."}, {"q": "¿Photomath es gratis?", "a": "Sí. La app principal de Photomath es totalmente gratuita, con soluciones paso a paso ilimitadas, escaneo con la cámara, calculadora, sin anuncios y sin límite de tiempo. Photomath Plus (9,99 $/mes o 69,99 $/año, unos 5,83 $/mes) añade explicaciones animadas y varios métodos de solución."}, {"q": "¿Khanmigo es gratis?", "a": "Para los docentes, sí: Khanmigo es gratis en más de 44 países, con el apoyo de Microsoft. Los estudiantes y las familias pagan 4 $/mes o 44 $/año (el plan anual ahorra unos dos meses), y una cuenta de madre o padre puede añadir hasta 10 hijos."}, {"q": "¿Puede Photomath resolver problemas de enunciado?", "a": "Sí. Puedes escribir o fotografiar problemas de texto, no solo ecuaciones, y Photomath resuelve problemas de álgebra con enunciado. Para problemas complejos con razonamiento de varios pasos puede convenir un tutor más amplio como Khanmigo."}]'::jsonb WHERE slug='khanmigo-vs-photomath' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du brauchst Hilfe in mehreren Schulfächern — nicht nur Mathe, sondern auch Naturwissenschaften, Geschichte und Schreiben", "✅ Du willst einen sokratischen Tutor, der dich mit Fragen zur Antwort führt, statt sie einfach zu lösen", "✅ Du bist Lehrkraft und suchst kostenlose KI-Tools für Unterrichtsplanung, Feedback und Vorbereitung", "✅ Du nutzt den Lehrplan der Khan Academy und möchtest KI direkt in diese Lektionen integriert haben"]', choose_b='["✅ Du brauchst schnelle Schritt-für-Schritt-Lösungen für Matheaufgaben per Foto auf dem Handy", "✅ Du willst sofort ausgearbeitete Antworten statt sokratischer Anleitung", "✅ Du bist Schüler oder Student und brauchst schnell Hilfe bei Mathe-Hausaufgaben — von Arithmetik bis Analysis", "✅ Du willst eine wirklich kostenlose Kern-App mit unbegrenzten Schritt-für-Schritt-Lösungen und ohne Werbung"]', faq='[{"q": "Was ist Khanmigo?", "a": "Khanmigo ist der GPT-4-basierte KI-Tutor der Khan Academy. Er nutzt die sokratische Methode — er stellt leitende Fragen, statt Antworten vorzugeben — und hilft beim Verständnis von Mathematik, Naturwissenschaften, Geschichte und Geisteswissenschaften. Die Khan Academy führt die multimodale GPT-4o-Integration ein und testet ein Redesign im Sommer 2026."}, {"q": "Ist Photomath kostenlos?", "a": "Ja. Die Kern-App von Photomath ist komplett kostenlos, mit unbegrenzten Schritt-für-Schritt-Lösungen, Kamera-Scan, Rechner, ohne Werbung und ohne Zeitlimit. Photomath Plus (9,99 $/Monat oder 69,99 $/Jahr, rund 5,83 $/Monat) ergänzt animierte Erklärungen und mehrere Lösungswege."}, {"q": "Ist Khanmigo kostenlos?", "a": "Für Lehrkräfte ja: Khanmigo ist in über 44 Ländern kostenlos, unterstützt von Microsoft. Lernende und Familien zahlen 4 $/Monat oder 44 $/Jahr (das Jahresabo spart rund zwei Monate), und ein Elternkonto kann bis zu 10 Kinder umfassen."}, {"q": "Kann Photomath Textaufgaben lösen?", "a": "Ja. Du kannst textbasierte Aufgaben eintippen oder fotografieren, nicht nur Gleichungen, und Photomath löst Algebra-Textaufgaben. Für komplexe mehrstufige Denkaufgaben eignet sich eher ein breiterer Tutor wie Khanmigo."}]'::jsonb WHERE slug='khanmigo-vs-photomath' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Вам потрібна допомога з кількох шкільних предметів — не лише з математики, а й з природничих наук, історії та письма", "✅ Ви хочете сократичного наставника, який навідними запитаннями веде вас до відповіді, а не просто розв''язує задачу", "✅ Ви викладач і шукаєте безкоштовні ШІ-інструменти для планування уроків, зворотного зв''язку та підготовки до занять", "✅ Ви навчаєтеся за програмою Khan Academy і хочете, щоб ШІ був вбудований прямо в ці уроки"]', choose_b='["✅ Вам потрібні швидкі покрокові розв''язання математичних задач просто з фотографії на телефоні", "✅ Вам потрібні готові відповіді одразу, а не сократичні підказки", "✅ Ви студент і вам терміново потрібна допомога з домашнім завданням з математики — від арифметики до матаналізу", "✅ Вам потрібен по-справжньому безкоштовний застосунок із безлімітними покроковими розв''язаннями та без реклами"]', faq='[{"q": "Що таке Khanmigo?", "a": "Khanmigo — це ШІ-репетитор Khan Academy на базі GPT-4. Він використовує сократичний метод — ставить навідні запитання замість готових відповідей — і допомагає розібратися в темах з математики, природничих наук, історії та гуманітарних дисциплін. Khan Academy впроваджує мультимодальну інтеграцію GPT-4o й тестує оновлений дизайн улітку 2026 року."}, {"q": "Чи Photomath безкоштовний?", "a": "Так. Основний застосунок Photomath повністю безкоштовний: безлімітні покрокові розв''язання, сканування камерою, калькулятор, без реклами й без обмежень у часі. Photomath Plus (9,99 $/місяць або 69,99 $/рік, близько 5,83 $/місяць) додає анімовані пояснення та кілька способів розв''язання."}, {"q": "Чи Khanmigo безкоштовний?", "a": "Для викладачів — так: Khanmigo безкоштовний у понад 44 країнах за підтримки Microsoft. Учні та батьки/родини платять 4 $/місяць або 44 $/рік (річний план заощаджує близько двох місяців), а до батьківського акаунта можна додати до 10 дітей."}, {"q": "Чи може Photomath розв''язувати текстові задачі?", "a": "Так. Можна ввести текст або сфотографувати текстову задачу, а не лише рівняння, і Photomath упорається з алгебраїчними текстовими задачами. Для складних задач із багатокроковими міркуваннями краще підійде ширший наставник на кшталт Khanmigo."}]'::jsonb WHERE slug='khanmigo-vs-photomath' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם צריכים עזרה בכמה מקצועות לימוד — לא רק במתמטיקה, אלא גם במדעים, בהיסטוריה ובכתיבה", "✅ אתם רוצים מורה סוקרטי שמוביל אתכם אל התשובה בעזרת שאלות במקום פשוט לפתור עבורכם", "✅ אתם מורים ומחפשים כלי בינה מלאכותית חינמיים לתכנון שיעורים, מתן משוב לתלמידים והכנה לכיתה", "✅ אתם לומדים לפי תוכנית הלימודים של Khan Academy ורוצים בינה מלאכותית משולבת ישירות בשיעורים"]', choose_b='["✅ אתם צריכים פתרונות מהירים שלב-אחר-שלב לבעיות מתמטיקה מתוך צילום בטלפון", "✅ אתם רוצים תשובות פתורות מיד ולא הכוונה סוקרטית", "✅ אתם תלמידים וצריכים עזרה מהירה בשיעורי בית במתמטיקה — מחשבון ועד חשבון דיפרנציאלי", "✅ אתם רוצים אפליקציה עם ליבה חינמית באמת, עם פתרונות שלב-אחר-שלב ללא הגבלה וללא פרסומות"]', faq='[{"q": "מה זה Khanmigo?", "a": "Khanmigo הוא המורה מבוסס הבינה המלאכותית של Khan Academy המונע על ידי GPT-4. הוא משתמש בשיטה הסוקרטית — שואל שאלות מנחות במקום לתת תשובות — כדי לעזור לתלמידים להבין מושגים במתמטיקה, מדעים, היסטוריה ומדעי הרוח. Khan Academy מטמיעה שילוב רב-מודלי של GPT-4o ומריצה פיילוט לעיצוב מחודש בקיץ 2026."}, {"q": "האם Photomath חינמי?", "a": "כן. אפליקציית הליבה של Photomath חינמית לחלוטין, עם פתרונות שלב-אחר-שלב ללא הגבלה, סריקת מצלמה, מחשבון, ללא פרסומות וללא הגבלת זמן. Photomath Plus (9.99$ לחודש או 69.99$ לשנה, כ-5.83$ לחודש) מוסיפה הסברים מונפשים ומספר דרכי פתרון."}, {"q": "האם Khanmigo חינמי?", "a": "למורים — כן: Khanmigo חינמי ביותר מ-44 מדינות, בתמיכת Microsoft. לומדים והורים/משפחות משלמים 4$ לחודש או 44$ לשנה (התוכנית השנתית חוסכת כחודשיים), וחשבון הורה יכול להוסיף עד 10 ילדים."}, {"q": "האם Photomath יכול לפתור בעיות מילוליות?", "a": "כן. אפשר להקליד או לצלם בעיות טקסטואליות, לא רק משוואות, ו-Photomath מתמודד עם בעיות אלגברה מילוליות. לבעיות מורכבות עם חשיבה רב-שלבית ייתכן שעדיף מורה רחב יותר כמו Khanmigo."}]'::jsonb WHERE slug='khanmigo-vs-photomath' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous avez besoin d''aide dans plusieurs matières scolaires — pas seulement les maths, mais aussi les sciences, l''histoire et l''écriture", "✅ Vous voulez un tuteur socratique qui vous guide vers la réponse par des questions plutôt que de la résoudre à votre place", "✅ Vous êtes enseignant et cherchez des outils d''IA gratuits pour préparer les cours, donner des retours aux élèves et organiser la classe", "✅ Vous suivez le programme de Khan Academy et voulez l''IA intégrée directement à ces leçons"]', choose_b='["✅ Vous avez besoin de solutions rapides, étape par étape, à des problèmes de maths à partir d''une photo sur votre téléphone", "✅ Vous voulez des réponses résolues immédiatement plutôt qu''un accompagnement socratique", "✅ Vous êtes élève et avez besoin d''aide rapide pour les devoirs de maths — de l''arithmétique au calcul différentiel", "✅ Vous voulez une application dont le cœur est réellement gratuit, avec des solutions étape par étape illimitées et sans publicité"]', faq='[{"q": "Qu''est-ce que Khanmigo ?", "a": "Khanmigo est le tuteur IA de Khan Academy propulsé par GPT-4. Il utilise la méthode socratique — il pose des questions d''orientation plutôt que de donner la réponse — pour aider les élèves à comprendre des concepts en maths, sciences, histoire et sciences humaines. Khan Academy déploie l''intégration multimodale GPT-4o et teste une refonte à l''été 2026."}, {"q": "Photomath est-il gratuit ?", "a": "Oui. L''application principale de Photomath est entièrement gratuite, avec des solutions étape par étape illimitées, le scan par caméra, une calculatrice, sans publicité et sans limite de temps. Photomath Plus (9,99 $/mois ou 69,99 $/an, soit environ 5,83 $/mois) ajoute des explications animées et plusieurs méthodes de résolution."}, {"q": "Khanmigo est-il gratuit ?", "a": "Pour les enseignants, oui : Khanmigo est gratuit dans plus de 44 pays, avec le soutien de Microsoft. Les apprenants et les familles paient 4 $/mois ou 44 $/an (l''abonnement annuel fait économiser environ deux mois), et un compte parent peut ajouter jusqu''à 10 enfants."}, {"q": "Photomath peut-il résoudre des problèmes rédigés ?", "a": "Oui. Vous pouvez saisir ou photographier des problèmes rédigés, pas seulement des équations, et Photomath traite les problèmes d''algèbre. Pour des problèmes complexes à raisonnement en plusieurs étapes, un tuteur plus polyvalent comme Khanmigo peut être préférable."}]'::jsonb WHERE slug='khanmigo-vs-photomath' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você precisa de ajuda em várias matérias — não só matemática, mas também ciências, história e escrita", "✅ Você quer um tutor socrático que o conduz à resposta com perguntas em vez de simplesmente resolvê-la", "✅ Você é professor e busca ferramentas de IA gratuitas para planejar aulas, dar feedback aos alunos e preparar a turma", "✅ Você usa o currículo da Khan Academy e quer a IA integrada diretamente a essas lições"]', choose_b='["✅ Você precisa de soluções rápidas, passo a passo, de problemas de matemática a partir de uma foto no celular", "✅ Você quer respostas resolvidas na hora, em vez de orientação socrática", "✅ Você é estudante e precisa de ajuda rápida com a lição de matemática — da aritmética ao cálculo", "✅ Você quer um app com núcleo realmente gratuito, com soluções passo a passo ilimitadas e sem anúncios"]', faq='[{"q": "O que é o Khanmigo?", "a": "O Khanmigo é o tutor de IA da Khan Academy movido por GPT-4. Ele usa o método socrático — faz perguntas orientadoras em vez de dar a resposta — para ajudar os alunos a entender conceitos de matemática, ciências, história e humanidades. A Khan Academy está implementando a integração multimodal do GPT-4o e testando um redesign no verão de 2026."}, {"q": "O Photomath é gratuito?", "a": "Sim. O app principal do Photomath é totalmente gratuito, com soluções passo a passo ilimitadas, digitalização por câmera, calculadora, sem anúncios e sem limite de tempo. O Photomath Plus (US$ 9,99/mês ou US$ 69,99/ano, cerca de US$ 5,83/mês) adiciona explicações animadas e vários métodos de solução."}, {"q": "O Khanmigo é gratuito?", "a": "Para professores, sim: o Khanmigo é gratuito em mais de 44 países, com apoio da Microsoft. Alunos e famílias pagam US$ 4/mês ou US$ 44/ano (o plano anual economiza cerca de dois meses), e uma conta de responsável pode incluir até 10 filhos."}, {"q": "O Photomath resolve problemas com enunciado?", "a": "Sim. Você pode digitar ou fotografar problemas em texto, não apenas equações, e o Photomath resolve problemas de álgebra com enunciado. Para problemas complexos com raciocínio de várias etapas, um tutor mais amplo como o Khanmigo pode ser mais indicado."}]'::jsonb WHERE slug='khanmigo-vs-photomath' AND lang='pt';

-- meta-ai-vs-chatgpt
UPDATE comparisons SET choose_a='["✅ You''re on WhatsApp, Instagram, Messenger, or Facebook and want AI help without switching apps", "✅ You want a strong free tier — Meta AI''s free access covers everyday questions for casual users", "✅ You want real-time web search results built into your AI conversations", "✅ You generate images casually with the built-in Muse Image model, right inside your social apps", "✅ You''d rather pay a low price if you upgrade — Meta One Plus is $7.99/month, Premium $19.99/month"]', choose_b='["✅ You need advanced tools: code interpreter, image generation, and voice mode in one place", "✅ You use AI for professional work: coding, research, analysis, and complex writing", "✅ You want a frontier flagship model — ChatGPT runs GPT-5.5 by default", "✅ You need reliable, consistent performance for high-stakes professional tasks", "✅ You want flexible plans: Free, Go at $8, Plus at $20, or Pro at $100-200/month"]', faq='[{"q": "What is Meta AI?", "a": "Meta AI is Meta''s assistant, powered by the Muse Spark model from Meta Superintelligence Labs and integrated into WhatsApp, Instagram, Facebook, and Messenger. It answers questions, generates images with the Muse Image model, searches the web in real time, and helps with tasks without leaving Meta''s apps."}, {"q": "Is Meta AI free?", "a": "Meta AI has a free tier that covers everyday use for casual users. Meta also offers paid consumer plans under the Meta One brand: Meta One Plus at $7.99/month and Meta One Premium at $19.99/month, plus business tiers such as Meta One Essential."}, {"q": "Is Meta AI as good as ChatGPT?", "a": "For general conversation and everyday questions, Meta AI (Muse Spark) is competitive. ChatGPT runs GPT-5.5 by default and offers more built-in tools such as a code interpreter, voice mode, and image generation, plus a larger app ecosystem. Meta AI wins on in-app accessibility; ChatGPT wins on depth of features for professional work."}, {"q": "Can Meta AI generate images?", "a": "Yes. Meta AI generates images from text prompts using Meta''s Muse Image model, directly inside Instagram, WhatsApp, and Messenger. It''s convenient for casual creation, though dedicated tools like Midjourney V7 still lead on top-end image quality."}]'::jsonb WHERE slug='meta-ai-vs-chatgpt' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вы пользуетесь WhatsApp, Instagram, Messenger или Facebook и хотите помощь ИИ без перехода в другие приложения", "✅ Вам нужен хороший бесплатный тариф — бесплатного доступа Meta AI хватает для повседневных вопросов", "✅ Вам важен поиск в интернете в реальном времени прямо в диалогах с ИИ", "✅ Вы генерируете картинки по-простому — встроенная модель Muse Image работает прямо в соцсетях", "✅ Если решите перейти на платный план, цена низкая: Meta One Plus $7,99/мес, Premium $19,99/мес"]', choose_b='["✅ Вам нужны продвинутые инструменты: интерпретатор кода, генерация изображений и голосовой режим", "✅ Вы используете ИИ для работы: программирование, исследования, анализ и сложные тексты", "✅ Вам нужна флагманская модель — по умолчанию ChatGPT работает на GPT-5.5", "✅ Вам важна стабильная и надёжная работа для ответственных задач", "✅ Вам нужны гибкие тарифы: Free, Go за $8, Plus за $20 или Pro за $100-200/мес"]', faq='[{"q": "Что такое Meta AI?", "a": "Meta AI — это ассистент Meta на базе модели Muse Spark от Meta Superintelligence Labs, встроенный в WhatsApp, Instagram, Facebook и Messenger. Он отвечает на вопросы, генерирует изображения через модель Muse Image, ищет в интернете в реальном времени и помогает с задачами прямо внутри приложений Meta."}, {"q": "Meta AI бесплатный?", "a": "У Meta AI есть бесплатный тариф, которого хватает для повседневного использования. Также есть платные планы под брендом Meta One: Meta One Plus за $7,99/мес и Meta One Premium за $19,99/мес, а также бизнес-тарифы, например Meta One Essential."}, {"q": "Meta AI не хуже ChatGPT?", "a": "Для обычного общения и повседневных вопросов Meta AI (Muse Spark) вполне конкурентоспособен. ChatGPT по умолчанию использует GPT-5.5 и предлагает больше встроенных инструментов — интерпретатор кода, голосовой режим, генерацию изображений — и более крупную экосистему приложений. Meta AI выигрывает в доступности внутри соцсетей, ChatGPT — в глубине функций для работы."}, {"q": "Может ли Meta AI генерировать изображения?", "a": "Да. Meta AI создаёт изображения по текстовым запросам с помощью модели Muse Image прямо в Instagram, WhatsApp и Messenger. Это удобно для простых задач, хотя специализированные инструменты вроде Midjourney V7 по-прежнему лидируют по максимальному качеству картинок."}]'::jsonb WHERE slug='meta-ai-vs-chatgpt' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Usas WhatsApp, Instagram, Messenger o Facebook y quieres ayuda de IA sin cambiar de app", "✅ Quieres un buen plan gratuito — el acceso gratis de Meta AI cubre las preguntas del día a día", "✅ Quieres búsqueda web en tiempo real integrada en tus conversaciones con la IA", "✅ Generas imágenes de forma casual con el modelo Muse Image, dentro de tus redes sociales", "✅ Si decides mejorar, el precio es bajo: Meta One Plus 7,99 $/mes y Premium 19,99 $/mes"]', choose_b='["✅ Necesitas herramientas avanzadas: intérprete de código, generación de imágenes y modo de voz", "✅ Usas la IA para trabajo profesional: programación, investigación, análisis y escritura compleja", "✅ Quieres un modelo insignia de vanguardia — ChatGPT usa GPT-5.5 por defecto", "✅ Necesitas un rendimiento fiable y constante para tareas profesionales importantes", "✅ Quieres planes flexibles: Free, Go por 8 $, Plus por 20 $ o Pro por 100-200 $/mes"]', faq='[{"q": "¿Qué es Meta AI?", "a": "Meta AI es el asistente de Meta, impulsado por el modelo Muse Spark de Meta Superintelligence Labs e integrado en WhatsApp, Instagram, Facebook y Messenger. Responde preguntas, genera imágenes con el modelo Muse Image, busca en la web en tiempo real y ayuda con tareas sin salir de las apps de Meta."}, {"q": "¿Meta AI es gratis?", "a": "Meta AI tiene un plan gratuito que cubre el uso cotidiano. Meta también ofrece planes de pago bajo la marca Meta One: Meta One Plus por 7,99 $/mes y Meta One Premium por 19,99 $/mes, además de niveles para empresas como Meta One Essential."}, {"q": "¿Es Meta AI tan bueno como ChatGPT?", "a": "Para conversación general y preguntas cotidianas, Meta AI (Muse Spark) es competitivo. ChatGPT usa GPT-5.5 por defecto y ofrece más herramientas integradas, como intérprete de código, modo de voz y generación de imágenes, además de un ecosistema de apps mayor. Meta AI gana en accesibilidad dentro de las apps; ChatGPT gana en profundidad de funciones para el trabajo profesional."}, {"q": "¿Puede Meta AI generar imágenes?", "a": "Sí. Meta AI genera imágenes a partir de texto con el modelo Muse Image de Meta, directamente en Instagram, WhatsApp y Messenger. Es cómodo para uso casual, aunque herramientas especializadas como Midjourney V7 siguen liderando en la máxima calidad de imagen."}]'::jsonb WHERE slug='meta-ai-vs-chatgpt' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du nutzt WhatsApp, Instagram, Messenger oder Facebook und willst KI-Hilfe ohne App-Wechsel", "✅ Du willst einen guten kostenlosen Tarif — der Gratiszugang von Meta AI deckt Alltagsfragen ab", "✅ Du willst Echtzeit-Websuche direkt in deinen KI-Gesprächen", "✅ Du erstellst Bilder ganz nebenbei mit dem integrierten Muse-Image-Modell in deinen Social-Apps", "✅ Falls du upgraden willst, ist der Preis niedrig: Meta One Plus 7,99 $/Monat, Premium 19,99 $/Monat"]', choose_b='["✅ Du brauchst fortgeschrittene Tools: Code-Interpreter, Bildgenerierung und Sprachmodus", "✅ Du nutzt KI für berufliche Arbeit: Programmieren, Recherche, Analyse und komplexe Texte", "✅ Du willst ein Spitzenmodell — ChatGPT nutzt standardmäßig GPT-5.5", "✅ Du brauchst zuverlässige, konstante Leistung für anspruchsvolle Aufgaben", "✅ Du willst flexible Tarife: Free, Go für 8 $, Plus für 20 $ oder Pro für 100-200 $/Monat"]', faq='[{"q": "Was ist Meta AI?", "a": "Meta AI ist der Assistent von Meta, angetrieben vom Muse-Spark-Modell der Meta Superintelligence Labs und integriert in WhatsApp, Instagram, Facebook und Messenger. Er beantwortet Fragen, erstellt Bilder mit dem Muse-Image-Modell, sucht in Echtzeit im Web und hilft bei Aufgaben, ohne die Meta-Apps zu verlassen."}, {"q": "Ist Meta AI kostenlos?", "a": "Meta AI hat einen kostenlosen Tarif, der den Alltagsgebrauch abdeckt. Meta bietet außerdem kostenpflichtige Tarife unter der Marke Meta One an: Meta One Plus für 7,99 $/Monat und Meta One Premium für 19,99 $/Monat, dazu Business-Stufen wie Meta One Essential."}, {"q": "Ist Meta AI so gut wie ChatGPT?", "a": "Für allgemeine Gespräche und Alltagsfragen ist Meta AI (Muse Spark) konkurrenzfähig. ChatGPT nutzt standardmäßig GPT-5.5 und bietet mehr integrierte Tools wie Code-Interpreter, Sprachmodus und Bildgenerierung sowie ein größeres App-Ökosystem. Meta AI punktet mit der Zugänglichkeit in den Apps, ChatGPT mit der Funktionstiefe für berufliche Arbeit."}, {"q": "Kann Meta AI Bilder erstellen?", "a": "Ja. Meta AI erstellt Bilder aus Textvorgaben mit Metas Muse-Image-Modell, direkt in Instagram, WhatsApp und Messenger. Das ist praktisch für den gelegentlichen Gebrauch, auch wenn spezialisierte Tools wie Midjourney V7 bei der Spitzenqualität weiterhin führen."}]'::jsonb WHERE slug='meta-ai-vs-chatgpt' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Ви користуєтеся WhatsApp, Instagram, Messenger чи Facebook і хочете допомогу ШІ без переходу в інші застосунки", "✅ Вам потрібен хороший безкоштовний тариф — безкоштовного доступу Meta AI вистачає на щоденні запитання", "✅ Вам важливий пошук в інтернеті в реальному часі прямо в діалогах зі ШІ", "✅ Ви генеруєте зображення просто — вбудована модель Muse Image працює прямо в соцмережах", "✅ Якщо вирішите перейти на платний план, ціна низька: Meta One Plus $7,99/міс, Premium $19,99/міс"]', choose_b='["✅ Вам потрібні просунуті інструменти: інтерпретатор коду, генерація зображень і голосовий режим", "✅ Ви використовуєте ШІ для роботи: програмування, дослідження, аналіз і складні тексти", "✅ Вам потрібна флагманська модель — за замовчуванням ChatGPT працює на GPT-5.5", "✅ Вам важлива стабільна й надійна робота для відповідальних завдань", "✅ Вам потрібні гнучкі тарифи: Free, Go за $8, Plus за $20 або Pro за $100-200/міс"]', faq='[{"q": "Що таке Meta AI?", "a": "Meta AI — це асистент Meta на базі моделі Muse Spark від Meta Superintelligence Labs, вбудований у WhatsApp, Instagram, Facebook і Messenger. Він відповідає на запитання, генерує зображення через модель Muse Image, шукає в інтернеті в реальному часі й допомагає із завданнями прямо всередині застосунків Meta."}, {"q": "Meta AI безкоштовний?", "a": "У Meta AI є безкоштовний тариф, якого вистачає для щоденного використання. Також є платні плани під брендом Meta One: Meta One Plus за $7,99/міс і Meta One Premium за $19,99/міс, а також бізнес-тарифи, як-от Meta One Essential."}, {"q": "Meta AI не гірший за ChatGPT?", "a": "Для звичайного спілкування та повсякденних запитань Meta AI (Muse Spark) цілком конкурентний. ChatGPT за замовчуванням використовує GPT-5.5 і пропонує більше вбудованих інструментів — інтерпретатор коду, голосовий режим, генерацію зображень — і більшу екосистему застосунків. Meta AI виграє в доступності всередині соцмереж, ChatGPT — у глибині функцій для роботи."}, {"q": "Чи може Meta AI генерувати зображення?", "a": "Так. Meta AI створює зображення за текстовими запитами за допомогою моделі Muse Image прямо в Instagram, WhatsApp і Messenger. Це зручно для простих завдань, хоча спеціалізовані інструменти на кшталт Midjourney V7 досі лідирують за максимальною якістю зображень."}]'::jsonb WHERE slug='meta-ai-vs-chatgpt' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם משתמשים ב-WhatsApp, ב-Instagram, ב-Messenger או ב-Facebook ורוצים עזרה מ-AI בלי לעבור אפליקציה", "✅ אתם רוצים תוכנית חינמית טובה — הגישה החינמית של Meta AI מספיקה לשאלות היומיום", "✅ אתם רוצים תוצאות חיפוש אינטרנט בזמן אמת משולבות בשיחות ה-AI", "✅ אתם יוצרים תמונות בקלילות עם מודל Muse Image המובנה, ישירות בתוך הרשתות החברתיות", "✅ אם תשדרגו, המחיר נמוך: Meta One Plus ב-7.99$ לחודש ו-Premium ב-19.99$ לחודש"]', choose_b='["✅ אתם צריכים כלים מתקדמים: מפרש קוד, יצירת תמונות ומצב קולי במקום אחד", "✅ אתם משתמשים ב-AI לעבודה מקצועית: תכנות, מחקר, ניתוח וכתיבה מורכבת", "✅ אתם רוצים מודל דגל מתקדם — ChatGPT מריץ את GPT-5.5 כברירת מחדל", "✅ אתם צריכים ביצועים אמינים ועקביים למשימות מקצועיות חשובות", "✅ אתם רוצים תוכניות גמישות: Free, ‏Go ב-8$, ‏Plus ב-20$ או Pro ב-100-200$ לחודש"]', faq='[{"q": "מה זה Meta AI?", "a": "Meta AI הוא העוזר של Meta, המופעל על ידי מודל Muse Spark של Meta Superintelligence Labs ומשולב ב-WhatsApp, ב-Instagram, ב-Facebook וב-Messenger. הוא עונה על שאלות, יוצר תמונות באמצעות מודל Muse Image, מחפש באינטרנט בזמן אמת ומסייע במשימות בלי לצאת מאפליקציות Meta."}, {"q": "האם Meta AI חינמי?", "a": "ל-Meta AI יש תוכנית חינמית המספיקה לשימוש יומיומי. Meta מציעה גם תוכניות בתשלום תחת המותג Meta One: ‏Meta One Plus ב-7.99$ לחודש ו-Meta One Premium ב-19.99$ לחודש, וכן רמות עסקיות כמו Meta One Essential."}, {"q": "האם Meta AI טוב כמו ChatGPT?", "a": "לשיחה כללית ולשאלות יומיום, Meta AI (‏Muse Spark) תחרותי. ChatGPT מריץ את GPT-5.5 כברירת מחדל ומציע יותר כלים מובנים כמו מפרש קוד, מצב קולי ויצירת תמונות, וכן מערכת אפליקציות רחבה יותר. Meta AI מנצח בנגישות בתוך האפליקציות, ChatGPT מנצח בעומק היכולות לעבודה מקצועית."}, {"q": "האם Meta AI יכול ליצור תמונות?", "a": "כן. Meta AI יוצר תמונות מטקסט באמצעות מודל Muse Image של Meta, ישירות ב-Instagram, ב-WhatsApp וב-Messenger. זה נוח לשימוש יומיומי, אם כי כלים ייעודיים כמו Midjourney V7 עדיין מובילים באיכות התמונה הגבוהה ביותר."}]'::jsonb WHERE slug='meta-ai-vs-chatgpt' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous utilisez WhatsApp, Instagram, Messenger ou Facebook et voulez l''aide de l''IA sans changer d''appli", "✅ Vous voulez une bonne offre gratuite — l''accès gratuit de Meta AI couvre les questions du quotidien", "✅ Vous voulez une recherche web en temps réel intégrée à vos conversations avec l''IA", "✅ Vous générez des images de façon occasionnelle avec le modèle Muse Image, au sein de vos réseaux sociaux", "✅ Si vous passez à un forfait payant, le prix est bas : Meta One Plus à 7,99 $/mois et Premium à 19,99 $/mois"]', choose_b='["✅ Vous avez besoin d''outils avancés : interpréteur de code, génération d''images et mode vocal", "✅ Vous utilisez l''IA pour un travail professionnel : code, recherche, analyse et écriture complexe", "✅ Vous voulez un modèle phare de pointe — ChatGPT utilise GPT-5.5 par défaut", "✅ Vous avez besoin de performances fiables et constantes pour des tâches à enjeux élevés", "✅ Vous voulez des offres flexibles : Free, Go à 8 $, Plus à 20 $ ou Pro à 100-200 $/mois"]', faq='[{"q": "Qu''est-ce que Meta AI ?", "a": "Meta AI est l''assistant de Meta, propulsé par le modèle Muse Spark des Meta Superintelligence Labs et intégré à WhatsApp, Instagram, Facebook et Messenger. Il répond aux questions, génère des images avec le modèle Muse Image, effectue des recherches web en temps réel et aide à réaliser des tâches sans quitter les applis de Meta."}, {"q": "Meta AI est-il gratuit ?", "a": "Meta AI propose une offre gratuite qui couvre l''usage quotidien. Meta propose aussi des forfaits payants sous la marque Meta One : Meta One Plus à 7,99 $/mois et Meta One Premium à 19,99 $/mois, ainsi que des offres pour les entreprises comme Meta One Essential."}, {"q": "Meta AI est-il aussi bon que ChatGPT ?", "a": "Pour la conversation générale et les questions du quotidien, Meta AI (Muse Spark) est compétitif. ChatGPT utilise GPT-5.5 par défaut et offre plus d''outils intégrés, comme l''interpréteur de code, le mode vocal et la génération d''images, ainsi qu''un écosystème d''applications plus large. Meta AI l''emporte sur l''accessibilité dans les applis ; ChatGPT l''emporte sur la profondeur des fonctionnalités pour le travail professionnel."}, {"q": "Meta AI peut-il générer des images ?", "a": "Oui. Meta AI génère des images à partir de texte grâce au modèle Muse Image de Meta, directement dans Instagram, WhatsApp et Messenger. C''est pratique pour un usage occasionnel, même si des outils spécialisés comme Midjourney V7 restent en tête pour la qualité d''image haut de gamme."}]'::jsonb WHERE slug='meta-ai-vs-chatgpt' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você usa WhatsApp, Instagram, Messenger ou Facebook e quer ajuda da IA sem trocar de app", "✅ Você quer um bom plano gratuito — o acesso grátis do Meta AI cobre as perguntas do dia a dia", "✅ Você quer busca na web em tempo real integrada às suas conversas com a IA", "✅ Você gera imagens de forma casual com o modelo Muse Image, dentro das suas redes sociais", "✅ Se decidir fazer upgrade, o preço é baixo: Meta One Plus a US$ 7,99/mês e Premium a US$ 19,99/mês"]', choose_b='["✅ Você precisa de ferramentas avançadas: interpretador de código, geração de imagens e modo de voz", "✅ Você usa IA para trabalho profissional: programação, pesquisa, análise e escrita complexa", "✅ Você quer um modelo de ponta — o ChatGPT usa o GPT-5.5 por padrão", "✅ Você precisa de desempenho confiável e consistente para tarefas importantes", "✅ Você quer planos flexíveis: Free, Go por US$ 8, Plus por US$ 20 ou Pro por US$ 100-200/mês"]', faq='[{"q": "O que é o Meta AI?", "a": "O Meta AI é o assistente da Meta, movido pelo modelo Muse Spark do Meta Superintelligence Labs e integrado ao WhatsApp, Instagram, Facebook e Messenger. Ele responde perguntas, gera imagens com o modelo Muse Image, pesquisa na web em tempo real e ajuda em tarefas sem sair dos apps da Meta."}, {"q": "O Meta AI é gratuito?", "a": "O Meta AI tem um plano gratuito que cobre o uso cotidiano. A Meta também oferece planos pagos sob a marca Meta One: Meta One Plus por US$ 7,99/mês e Meta One Premium por US$ 19,99/mês, além de níveis para empresas como o Meta One Essential."}, {"q": "O Meta AI é tão bom quanto o ChatGPT?", "a": "Para conversas gerais e perguntas do dia a dia, o Meta AI (Muse Spark) é competitivo. O ChatGPT usa o GPT-5.5 por padrão e oferece mais ferramentas integradas, como interpretador de código, modo de voz e geração de imagens, além de um ecossistema de apps maior. O Meta AI vence na acessibilidade dentro dos apps; o ChatGPT vence na profundidade de recursos para trabalho profissional."}, {"q": "O Meta AI pode gerar imagens?", "a": "Sim. O Meta AI gera imagens a partir de texto usando o modelo Muse Image da Meta, diretamente no Instagram, WhatsApp e Messenger. É prático para uso casual, embora ferramentas especializadas como o Midjourney V7 ainda liderem na qualidade de imagem de ponta."}]'::jsonb WHERE slug='meta-ai-vs-chatgpt' AND lang='pt';

-- microsoft-copilot-vs-chatgpt
UPDATE comparisons SET choose_a='["✅ You''re deep in the Microsoft ecosystem — Windows, Edge, and Microsoft 365", "✅ You want a capable AI assistant for free — Copilot Free runs the latest GPT-5 models with web search and citations, Think Deeper, voice, and image generation", "✅ You need AI built into Word, Excel, PowerPoint, and Outlook — Microsoft 365 Copilot runs GPT-5.4 Thinking and can read your own documents, spreadsheets, and email", "✅ You want an assistant that lives in your Windows taskbar and Edge browser and works across your files and apps"]', choose_b='["✅ You want OpenAI''s flagship model — ChatGPT defaults to GPT-5.5, with GPT-5.6 available in the API", "✅ You use AI for professional work: coding, data analysis, research, and complex writing", "✅ You want the broadest feature set — image generation, advanced voice, custom GPTs, and deep research", "✅ You build on the API — OpenAI''s developer platform is the most mature and widely adopted"]', faq='[{"q": "What is the difference between Microsoft Copilot and ChatGPT?", "a": "Both are powered by OpenAI''s GPT-5 family, but they''re packaged differently. Microsoft Copilot is built into Windows, Edge, and Microsoft 365, and can work directly with your Office files. ChatGPT is OpenAI''s standalone product with the widest feature set and its default flagship model, GPT-5.5. Copilot is best if you live in the Microsoft ecosystem; ChatGPT is best for the fullest, most flexible AI experience."}, {"q": "Is Microsoft Copilot free?", "a": "Yes. Copilot Free gives you access to the latest GPT-5 models when capacity allows, web search with citations, Think Deeper, voice, and roughly 15 image-generation boosts per day. AI inside the Office apps requires Microsoft 365 Copilot, a paid add-on to a Microsoft 365 subscription."}, {"q": "Does Microsoft Copilot use ChatGPT?", "a": "Copilot is powered by the same underlying OpenAI GPT-5 models as ChatGPT, through Microsoft''s partnership with OpenAI. Consumer Copilot defaults to GPT-5 / GPT-5.5 with Smart mode and Think Deeper, while Microsoft 365 Copilot runs GPT-5.4 Thinking. It isn''t the ChatGPT app itself, but it shares the same model family."}, {"q": "Which is better for Office tasks — Copilot or ChatGPT?", "a": "Microsoft 365 Copilot is better inside Office apps because it can read your existing Word documents, Excel spreadsheets, and email to give contextual help, running GPT-5.4 Thinking. ChatGPT requires you to paste content in manually, but is more flexible for open-ended writing and reasoning outside of Office."}]'::jsonb WHERE slug='microsoft-copilot-vs-chatgpt' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вы плотно работаете в экосистеме Microsoft — Windows, Edge и Microsoft 365", "✅ Вам нужен мощный ИИ-помощник бесплатно — Copilot Free работает на новейших моделях GPT-5 с веб-поиском и ссылками на источники, режимом Think Deeper, голосом и генерацией изображений", "✅ Вам нужен ИИ прямо в Word, Excel, PowerPoint и Outlook — Microsoft 365 Copilot работает на GPT-5.4 Thinking и читает ваши документы, таблицы и почту", "✅ Вам нужен помощник в панели задач Windows и в браузере Edge, работающий с вашими файлами и приложениями"]', choose_b='["✅ Вам нужна флагманская модель OpenAI — ChatGPT по умолчанию использует GPT-5.5, а GPT-5.6 доступна в API", "✅ Вы используете ИИ для профессиональной работы: программирование, анализ данных, исследования и сложные тексты", "✅ Вам нужен самый широкий набор функций — генерация изображений, продвинутый голос, кастомные GPT и глубокие исследования", "✅ Вы разрабатываете на API — платформа для разработчиков OpenAI самая зрелая и распространённая"]', faq='[{"q": "В чём разница между Microsoft Copilot и ChatGPT?", "a": "Оба работают на моделях OpenAI семейства GPT-5, но упакованы по-разному. Microsoft Copilot встроен в Windows, Edge и Microsoft 365 и может работать напрямую с вашими файлами Office. ChatGPT — самостоятельный продукт OpenAI с самым широким набором функций и флагманской моделью GPT-5.5 по умолчанию. Copilot удобнее, если вы живёте в экосистеме Microsoft; ChatGPT лучше для максимально полного и гибкого опыта."}, {"q": "Бесплатен ли Microsoft Copilot?", "a": "Да. Copilot Free даёт доступ к новейшим моделям GPT-5 при наличии мощностей, веб-поиск со ссылками, Think Deeper, голос и примерно 15 усилений генерации изображений в день. ИИ внутри приложений Office требует Microsoft 365 Copilot — платного дополнения к подписке Microsoft 365."}, {"q": "Использует ли Microsoft Copilot ChatGPT?", "a": "Copilot работает на тех же базовых моделях OpenAI GPT-5, что и ChatGPT, благодаря партнёрству Microsoft с OpenAI. Потребительский Copilot по умолчанию использует GPT-5 / GPT-5.5 с режимом Smart и Think Deeper, а Microsoft 365 Copilot — GPT-5.4 Thinking. Это не само приложение ChatGPT, но семейство моделей у них общее."}, {"q": "Что лучше для задач в Office — Copilot или ChatGPT?", "a": "Microsoft 365 Copilot лучше внутри приложений Office, потому что читает ваши документы Word, таблицы Excel и почту для контекстной помощи, работая на GPT-5.4 Thinking. ChatGPT требует вставлять содержимое вручную, но гибче для свободных текстов и рассуждений вне Office."}]'::jsonb WHERE slug='microsoft-copilot-vs-chatgpt' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Trabajas a fondo en el ecosistema de Microsoft — Windows, Edge y Microsoft 365", "✅ Quieres un asistente de IA potente y gratis — Copilot Free usa los últimos modelos GPT-5 con búsqueda web y citas, Think Deeper, voz y generación de imágenes", "✅ Necesitas IA integrada en Word, Excel, PowerPoint y Outlook — Microsoft 365 Copilot usa GPT-5.4 Thinking y puede leer tus documentos, hojas de cálculo y correo", "✅ Quieres un asistente en la barra de tareas de Windows y el navegador Edge que funcione con tus archivos y aplicaciones"]', choose_b='["✅ Quieres el modelo insignia de OpenAI — ChatGPT usa GPT-5.5 por defecto, con GPT-5.6 disponible en la API", "✅ Usas la IA para trabajo profesional: programación, análisis de datos, investigación y escritura compleja", "✅ Quieres el conjunto de funciones más amplio — generación de imágenes, voz avanzada, GPT personalizados e investigación profunda", "✅ Desarrollas sobre la API — la plataforma para desarrolladores de OpenAI es la más madura y extendida"]', faq='[{"q": "¿Cuál es la diferencia entre Microsoft Copilot y ChatGPT?", "a": "Ambos funcionan con la familia GPT-5 de OpenAI, pero se presentan de forma distinta. Microsoft Copilot está integrado en Windows, Edge y Microsoft 365, y puede trabajar directamente con tus archivos de Office. ChatGPT es el producto independiente de OpenAI, con el conjunto de funciones más amplio y su modelo insignia por defecto, GPT-5.5. Copilot es mejor si vives en el ecosistema de Microsoft; ChatGPT, para la experiencia de IA más completa y flexible."}, {"q": "¿Es gratis Microsoft Copilot?", "a": "Sí. Copilot Free da acceso a los últimos modelos GPT-5 cuando hay capacidad, búsqueda web con citas, Think Deeper, voz y unos 15 impulsos de generación de imágenes al día. La IA dentro de las apps de Office requiere Microsoft 365 Copilot, un complemento de pago sobre una suscripción a Microsoft 365."}, {"q": "¿Usa Microsoft Copilot ChatGPT?", "a": "Copilot funciona con los mismos modelos base GPT-5 de OpenAI que ChatGPT, gracias a la alianza de Microsoft con OpenAI. El Copilot de consumo usa GPT-5 / GPT-5.5 por defecto con modo Smart y Think Deeper, mientras que Microsoft 365 Copilot usa GPT-5.4 Thinking. No es la app de ChatGPT en sí, pero comparte la misma familia de modelos."}, {"q": "¿Cuál es mejor para tareas de Office — Copilot o ChatGPT?", "a": "Microsoft 365 Copilot es mejor dentro de las apps de Office porque puede leer tus documentos de Word, hojas de Excel y correo para dar ayuda contextual, con GPT-5.4 Thinking. ChatGPT te obliga a pegar el contenido manualmente, pero es más flexible para escritura y razonamiento abiertos fuera de Office."}]'::jsonb WHERE slug='microsoft-copilot-vs-chatgpt' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du arbeitest tief im Microsoft-Ökosystem — Windows, Edge und Microsoft 365", "✅ Du willst einen leistungsstarken KI-Assistenten kostenlos — Copilot Free nutzt die neuesten GPT-5-Modelle mit Websuche samt Quellenangaben, Think Deeper, Sprache und Bildgenerierung", "✅ Du brauchst KI direkt in Word, Excel, PowerPoint und Outlook — Microsoft 365 Copilot läuft mit GPT-5.4 Thinking und kann deine Dokumente, Tabellen und E-Mails lesen", "✅ Du willst einen Assistenten in der Windows-Taskleiste und im Edge-Browser, der mit deinen Dateien und Apps arbeitet"]', choose_b='["✅ Du willst OpenAIs Flaggschiff-Modell — ChatGPT nutzt standardmäßig GPT-5.5, GPT-5.6 ist über die API verfügbar", "✅ Du nutzt KI für professionelle Arbeit: Programmieren, Datenanalyse, Recherche und anspruchsvolles Schreiben", "✅ Du willst den breitesten Funktionsumfang — Bildgenerierung, fortgeschrittene Sprache, eigene GPTs und Deep Research", "✅ Du entwickelst auf der API — OpenAIs Entwicklerplattform ist die ausgereifteste und am weitesten verbreitete"]', faq='[{"q": "Was ist der Unterschied zwischen Microsoft Copilot und ChatGPT?", "a": "Beide basieren auf OpenAIs GPT-5-Familie, sind aber unterschiedlich verpackt. Microsoft Copilot ist in Windows, Edge und Microsoft 365 integriert und kann direkt mit deinen Office-Dateien arbeiten. ChatGPT ist OpenAIs eigenständiges Produkt mit dem breitesten Funktionsumfang und dem Standard-Flaggschiff GPT-5.5. Copilot ist ideal, wenn du im Microsoft-Ökosystem lebst; ChatGPT für das vollständigste, flexibelste KI-Erlebnis."}, {"q": "Ist Microsoft Copilot kostenlos?", "a": "Ja. Copilot Free bietet Zugang zu den neuesten GPT-5-Modellen, wenn Kapazität verfügbar ist, Websuche mit Quellenangaben, Think Deeper, Sprache und etwa 15 Bildgenerierungs-Boosts pro Tag. KI innerhalb der Office-Apps erfordert Microsoft 365 Copilot, ein kostenpflichtiges Add-on zu einem Microsoft-365-Abonnement."}, {"q": "Nutzt Microsoft Copilot ChatGPT?", "a": "Copilot basiert auf denselben zugrunde liegenden OpenAI-GPT-5-Modellen wie ChatGPT, durch die Partnerschaft von Microsoft mit OpenAI. Der Consumer-Copilot nutzt standardmäßig GPT-5 / GPT-5.5 mit Smart-Modus und Think Deeper, während Microsoft 365 Copilot GPT-5.4 Thinking verwendet. Es ist nicht die ChatGPT-App selbst, teilt aber dieselbe Modellfamilie."}, {"q": "Was ist besser für Office-Aufgaben — Copilot oder ChatGPT?", "a": "Microsoft 365 Copilot ist innerhalb der Office-Apps besser, weil es deine vorhandenen Word-Dokumente, Excel-Tabellen und E-Mails lesen kann, um kontextbezogene Hilfe zu geben — mit GPT-5.4 Thinking. ChatGPT erfordert das manuelle Einfügen von Inhalten, ist aber flexibler für offenes Schreiben und Denken außerhalb von Office."}]'::jsonb WHERE slug='microsoft-copilot-vs-chatgpt' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Ви щільно працюєте в екосистемі Microsoft — Windows, Edge та Microsoft 365", "✅ Вам потрібен потужний ШІ-помічник безкоштовно — Copilot Free працює на найновіших моделях GPT-5 з веб-пошуком і посиланнями на джерела, режимом Think Deeper, голосом і генерацією зображень", "✅ Вам потрібен ШІ прямо у Word, Excel, PowerPoint та Outlook — Microsoft 365 Copilot працює на GPT-5.4 Thinking і читає ваші документи, таблиці та пошту", "✅ Вам потрібен помічник у панелі завдань Windows і в браузері Edge, що працює з вашими файлами й застосунками"]', choose_b='["✅ Вам потрібна флагманська модель OpenAI — ChatGPT за замовчуванням використовує GPT-5.5, а GPT-5.6 доступна в API", "✅ Ви використовуєте ШІ для професійної роботи: програмування, аналіз даних, дослідження та складні тексти", "✅ Вам потрібен найширший набір функцій — генерація зображень, розширений голос, кастомні GPT та глибокі дослідження", "✅ Ви розробляєте на API — платформа для розробників OpenAI найзріліша та найпоширеніша"]', faq='[{"q": "Яка різниця між Microsoft Copilot і ChatGPT?", "a": "Обидва працюють на моделях OpenAI сімейства GPT-5, але подані по-різному. Microsoft Copilot вбудований у Windows, Edge та Microsoft 365 і може працювати безпосередньо з вашими файлами Office. ChatGPT — окремий продукт OpenAI з найширшим набором функцій і флагманською моделлю GPT-5.5 за замовчуванням. Copilot кращий, якщо ви живете в екосистемі Microsoft; ChatGPT — для максимально повного та гнучкого досвіду."}, {"q": "Чи безкоштовний Microsoft Copilot?", "a": "Так. Copilot Free дає доступ до найновіших моделей GPT-5 за наявності потужностей, веб-пошук із посиланнями, Think Deeper, голос і близько 15 підсилень генерації зображень на день. ШІ всередині застосунків Office потребує Microsoft 365 Copilot — платного доповнення до підписки Microsoft 365."}, {"q": "Чи використовує Microsoft Copilot ChatGPT?", "a": "Copilot працює на тих самих базових моделях OpenAI GPT-5, що й ChatGPT, завдяки партнерству Microsoft з OpenAI. Споживчий Copilot за замовчуванням використовує GPT-5 / GPT-5.5 з режимом Smart і Think Deeper, а Microsoft 365 Copilot — GPT-5.4 Thinking. Це не сам застосунок ChatGPT, але сімейство моделей у них спільне."}, {"q": "Що краще для завдань в Office — Copilot чи ChatGPT?", "a": "Microsoft 365 Copilot кращий усередині застосунків Office, бо може читати ваші наявні документи Word, таблиці Excel і пошту для контекстної допомоги, працюючи на GPT-5.4 Thinking. ChatGPT вимагає вставляти вміст вручну, але гнучкіший для вільних текстів і міркувань поза Office."}]'::jsonb WHERE slug='microsoft-copilot-vs-chatgpt' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם עובדים לעומק בתוך המערכת האקולוגית של Microsoft — Windows, Edge ו-Microsoft 365", "✅ אתם רוצים עוזר AI חזק בחינם — Copilot Free פועל עם מודלי GPT-5 החדשים ביותר, כולל חיפוש באינטרנט עם מקורות, Think Deeper, קול ויצירת תמונות", "✅ אתם צריכים AI מובנה ב-Word, Excel, PowerPoint ו-Outlook — Microsoft 365 Copilot פועל עם GPT-5.4 Thinking ויכול לקרוא את המסמכים, הגיליונות והדוא\"ל שלכם", "✅ אתם רוצים עוזר שיושב בשורת המשימות של Windows ובדפדפן Edge ועובד עם הקבצים והאפליקציות שלכם"]', choose_b='["✅ אתם רוצים את מודל הדגל של OpenAI — ChatGPT משתמש כברירת מחדל ב-GPT-5.5, ו-GPT-5.6 זמין ב-API", "✅ אתם משתמשים ב-AI לעבודה מקצועית: תכנות, ניתוח נתונים, מחקר וכתיבה מורכבת", "✅ אתם רוצים את מגוון התכונות הרחב ביותר — יצירת תמונות, קול מתקדם, GPT מותאמים אישית ומחקר מעמיק", "✅ אתם מפתחים על ה-API — פלטפורמת המפתחים של OpenAI היא הבשלה והנפוצה ביותר"]', faq='[{"q": "מה ההבדל בין Microsoft Copilot ל-ChatGPT?", "a": "שניהם פועלים על משפחת GPT-5 של OpenAI, אך ארוזים אחרת. Microsoft Copilot מובנה ב-Windows, ב-Edge וב-Microsoft 365 ויכול לעבוד ישירות עם קבצי ה-Office שלכם. ChatGPT הוא המוצר העצמאי של OpenAI עם מגוון התכונות הרחב ביותר ומודל הדגל שלו כברירת מחדל, GPT-5.5. Copilot מתאים אם אתם חיים בתוך המערכת של Microsoft; ChatGPT מתאים לחוויית AI המלאה והגמישה ביותר."}, {"q": "האם Microsoft Copilot חינמי?", "a": "כן. Copilot Free מעניק גישה למודלי GPT-5 החדשים ביותר כשיש קיבולת, חיפוש באינטרנט עם מקורות, Think Deeper, קול וכ-15 תגבורים ליצירת תמונות ביום. AI בתוך אפליקציות Office דורש את Microsoft 365 Copilot, תוסף בתשלום למנוי Microsoft 365."}, {"q": "האם Microsoft Copilot משתמש ב-ChatGPT?", "a": "Copilot פועל על אותם מודלי GPT-5 בסיסיים של OpenAI כמו ChatGPT, בזכות השותפות של Microsoft עם OpenAI. גרסת הצרכן של Copilot משתמשת כברירת מחדל ב-GPT-5 / GPT-5.5 עם מצב Smart ו-Think Deeper, בעוד ש-Microsoft 365 Copilot פועל עם GPT-5.4 Thinking. זו אינה אפליקציית ChatGPT עצמה, אך היא חולקת את אותה משפחת מודלים."}, {"q": "מה עדיף למשימות Office — Copilot או ChatGPT?", "a": "Microsoft 365 Copilot עדיף בתוך אפליקציות Office מכיוון שהוא יכול לקרוא את מסמכי ה-Word, גיליונות ה-Excel והדוא\"ל הקיימים שלכם כדי לתת עזרה מותאמת הקשר, בהפעלת GPT-5.4 Thinking. ChatGPT מחייב אתכם להדביק תוכן ידנית, אך גמיש יותר לכתיבה וחשיבה חופשית מחוץ ל-Office."}]'::jsonb WHERE slug='microsoft-copilot-vs-chatgpt' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous travaillez en profondeur dans l''écosystème Microsoft — Windows, Edge et Microsoft 365", "✅ Vous voulez un assistant IA puissant et gratuit — Copilot Free utilise les derniers modèles GPT-5 avec recherche web et citations, Think Deeper, voix et génération d''images", "✅ Vous avez besoin de l''IA intégrée à Word, Excel, PowerPoint et Outlook — Microsoft 365 Copilot fonctionne avec GPT-5.4 Thinking et peut lire vos documents, feuilles de calcul et e-mails", "✅ Vous voulez un assistant dans la barre des tâches Windows et le navigateur Edge, qui fonctionne avec vos fichiers et applications"]', choose_b='["✅ Vous voulez le modèle phare d''OpenAI — ChatGPT utilise GPT-5.5 par défaut, avec GPT-5.6 disponible dans l''API", "✅ Vous utilisez l''IA pour un travail professionnel : programmation, analyse de données, recherche et écriture complexe", "✅ Vous voulez l''ensemble de fonctionnalités le plus large — génération d''images, voix avancée, GPT personnalisés et recherche approfondie", "✅ Vous développez sur l''API — la plateforme pour développeurs d''OpenAI est la plus mature et la plus répandue"]', faq='[{"q": "Quelle est la différence entre Microsoft Copilot et ChatGPT ?", "a": "Les deux reposent sur la famille GPT-5 d''OpenAI, mais sont présentés différemment. Microsoft Copilot est intégré à Windows, Edge et Microsoft 365, et peut travailler directement avec vos fichiers Office. ChatGPT est le produit autonome d''OpenAI, avec l''ensemble de fonctionnalités le plus large et son modèle phare par défaut, GPT-5.5. Copilot est idéal si vous vivez dans l''écosystème Microsoft ; ChatGPT pour l''expérience IA la plus complète et flexible."}, {"q": "Microsoft Copilot est-il gratuit ?", "a": "Oui. Copilot Free donne accès aux derniers modèles GPT-5 lorsque la capacité le permet, à la recherche web avec citations, à Think Deeper, à la voix et à environ 15 boosts de génération d''images par jour. L''IA au sein des applications Office nécessite Microsoft 365 Copilot, un module payant ajouté à un abonnement Microsoft 365."}, {"q": "Microsoft Copilot utilise-t-il ChatGPT ?", "a": "Copilot repose sur les mêmes modèles OpenAI GPT-5 sous-jacents que ChatGPT, grâce au partenariat de Microsoft avec OpenAI. Le Copilot grand public utilise par défaut GPT-5 / GPT-5.5 avec le mode Smart et Think Deeper, tandis que Microsoft 365 Copilot fonctionne avec GPT-5.4 Thinking. Ce n''est pas l''application ChatGPT elle-même, mais il partage la même famille de modèles."}, {"q": "Lequel est meilleur pour les tâches Office — Copilot ou ChatGPT ?", "a": "Microsoft 365 Copilot est meilleur au sein des applications Office car il peut lire vos documents Word, feuilles Excel et e-mails existants pour fournir une aide contextuelle, avec GPT-5.4 Thinking. ChatGPT exige de coller le contenu manuellement, mais reste plus flexible pour l''écriture et le raisonnement libres en dehors d''Office."}]'::jsonb WHERE slug='microsoft-copilot-vs-chatgpt' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você trabalha a fundo no ecossistema da Microsoft — Windows, Edge e Microsoft 365", "✅ Você quer um assistente de IA potente e gratuito — o Copilot Free usa os modelos GPT-5 mais recentes com busca na web e citações, Think Deeper, voz e geração de imagens", "✅ Você precisa de IA integrada ao Word, Excel, PowerPoint e Outlook — o Microsoft 365 Copilot roda com GPT-5.4 Thinking e pode ler seus documentos, planilhas e e-mails", "✅ Você quer um assistente na barra de tarefas do Windows e no navegador Edge, que funcione com seus arquivos e aplicativos"]', choose_b='["✅ Você quer o modelo principal da OpenAI — o ChatGPT usa GPT-5.5 por padrão, com GPT-5.6 disponível na API", "✅ Você usa IA para trabalho profissional: programação, análise de dados, pesquisa e escrita complexa", "✅ Você quer o conjunto de recursos mais amplo — geração de imagens, voz avançada, GPTs personalizados e pesquisa aprofundada", "✅ Você desenvolve na API — a plataforma para desenvolvedores da OpenAI é a mais madura e amplamente adotada"]', faq='[{"q": "Qual é a diferença entre o Microsoft Copilot e o ChatGPT?", "a": "Ambos funcionam com a família GPT-5 da OpenAI, mas são empacotados de formas diferentes. O Microsoft Copilot é integrado ao Windows, Edge e Microsoft 365, e pode trabalhar diretamente com seus arquivos do Office. O ChatGPT é o produto independente da OpenAI, com o conjunto de recursos mais amplo e seu modelo principal por padrão, o GPT-5.5. O Copilot é melhor se você vive no ecossistema da Microsoft; o ChatGPT, para a experiência de IA mais completa e flexível."}, {"q": "O Microsoft Copilot é gratuito?", "a": "Sim. O Copilot Free dá acesso aos modelos GPT-5 mais recentes quando há capacidade, busca na web com citações, Think Deeper, voz e cerca de 15 impulsos de geração de imagens por dia. A IA dentro dos aplicativos do Office exige o Microsoft 365 Copilot, um complemento pago a uma assinatura do Microsoft 365."}, {"q": "O Microsoft Copilot usa o ChatGPT?", "a": "O Copilot funciona com os mesmos modelos base GPT-5 da OpenAI que o ChatGPT, graças à parceria da Microsoft com a OpenAI. O Copilot de consumo usa GPT-5 / GPT-5.5 por padrão, com modo Smart e Think Deeper, enquanto o Microsoft 365 Copilot roda com GPT-5.4 Thinking. Não é o aplicativo ChatGPT em si, mas compartilha a mesma família de modelos."}, {"q": "Qual é melhor para tarefas do Office — Copilot ou ChatGPT?", "a": "O Microsoft 365 Copilot é melhor dentro dos aplicativos do Office porque pode ler seus documentos do Word, planilhas do Excel e e-mails existentes para dar ajuda contextual, rodando com GPT-5.4 Thinking. O ChatGPT exige que você cole o conteúdo manualmente, mas é mais flexível para escrita e raciocínio abertos fora do Office."}]'::jsonb WHERE slug='microsoft-copilot-vs-chatgpt' AND lang='pt';
